var R = [
{id:'lavakakut',c:'kakku',n:['Lavakakut','Lava cakes'],v:1,f:'2212',note:['Taikina: 72 kpl.','Batter: 72 pcs.'],p:[{t:['Suklaatryffeli','Chocolate truffle'],i:[[1,'l','Kookoskerma','Coconut cream'],[1333,'g','Tumma suklaa','Dark chocolate'],[null,'','Kaakaojauhe pyörittelyyn','Cocoa powder for rolling']],s:[['Sulata kerma ja suklaa yhdessä ja kaada vuokaan tai pakkiin. Nosta kylmään kovettumaan.','Melt the cream and chocolate together and pour into a tray or box. Chill until firm.'],['Kun suklaaseos on kovettunut, punnaa massasta 10–15 g paloja. Pyöritä palloiksi ja pyöräytä kaakaojauheessa. Nosta pallot pakastimeen.','When set, weigh 10–15 g pieces. Roll into balls and roll in cocoa powder. Put the balls in the freezer.']]},{t:['Taikina (72 kpl)','Batter (72 pcs)'],i:[[480,'g','Kaakaojauhe','Cocoa powder'],[960,'g','Vehnäjauho','Wheat flour'],[40,'g','Leivinjauhe','Baking powder'],[20,'g','Ruokasooda','Baking soda'],[80,'g','Vaniljasokeri','Vanilla sugar'],[1200,'g','Ruokokidesokeri','Cane sugar'],[12,'g','Suola','Salt'],[2,'l','Kookoskerma','Coconut cream'],[600,'g','Vegevoi (Eleplant), sulatettu','Vegan butter (Eleplant), melted'],[240,'g','Vaalea balsamietikka','White balsamic vinegar']],s:[['Sekoita kuivat aineet keskenään. Sekoita nestemäiset keskenään. Yhdistä kuivat ja nestemäiset.','Mix the dry ingredients. Mix the wet ingredients. Combine dry and wet.'],['Pursota silikonisten muffinssivuokien pohjille vähän taikinaa, lisää suklaatryffeli ja piilota tryffeli taikinalla. Älä pursota taikinaa aivan vuoan reunalle asti.','Pipe a little batter into silicone muffin moulds, add a truffle and cover it with batter. Do not fill to the very top.'],['Paista 200 °C 8 min.','Bake at 200 °C for 8 min.'],['Jäähdytä hyvin pakkasen kautta ennen vuoasta irrottamista.','Chill well in the freezer before removing from the moulds.']]}]},
{id:'sitruuna-pistaasitiramisu',c:'jalki',n:['Sitruuna-pistaasitiramisu','Lemon-pistachio tiramisu'],f:'2213',note:['Mascarponevaahto: 40 kpl. Paperissa käsin myös ½× ja 1,5× määrät.','Mascarpone foam: 40 pcs. Paper also has ½× and 1.5× amounts by hand.'],p:[{t:['Mascarponevaahto (40 kpl)','Mascarpone foam (40 pcs)'],i:[[300,'g','Sokeri','Sugar'],[360,'g','Keltuainen','Egg yolk'],[1,'rkl','Vanilja-aromi','Vanilla extract'],[1350,'g','Mascarpone','Mascarpone'],[840,'g','Kuohukerma, vaahdotettu','Whipping cream, whipped']],s:[['Vaahdota keltuainen ja sokeri vesihauteessa paksuksi vaahdoksi.','Whisk the yolks and sugar over a water bath to a thick foam.'],['Ota pois vesihauteesta ja lisää mascarpone ja vanilja.','Take off the water bath and add the mascarpone and vanilla.'],['Nostele lopuksi joukkoon vaahdotettu kerma.','Finally fold in the whipped cream.']]},{t:['Limoncellokostutus','Limoncello soak'],i:[[933,'g','Sitruunamehu, siivilöity','Lemon juice, strained'],[2240,'g','Vesi','Water'],[933,'g','Sokeri','Sugar'],[700,'ml','Limoncello','Limoncello']],s:[['Keitä vettä ja sokeria n. 5 min.','Boil the water and sugar for about 5 min.'],['Lisää sitruunamehu ja limoncello.','Add the lemon juice and limoncello.']]},{t:['Pistaasikastike','Pistachio sauce'],i:[[397,'g','Kondensoitu maito (1 prk)','Condensed milk (1 can)'],[50,'g','Pistaasitahna','Pistachio paste'],[3,'g','Suola (½ tl)','Salt (½ tsp)']],s:[['Sekoita kaikki sekaisin.','Mix everything together.'],['Pussita.','Put into a piping bag.']]},{t:['Lemon curd','Lemon curd'],i:[[2,'kpl','Sitruunankuori','Lemon zest'],[1,'dl','Sitruunamehu, siivilöity','Lemon juice, strained'],[240,'g','Tomusokeri','Icing sugar'],[2,'kpl','Kananmuna','Egg'],[100,'g','Voi, kylmä','Butter, cold']],s:[['Kiehauta kattilassa kaikki muut aineet paitsi voi.','Bring everything except the butter to the boil in a pan.'],['Kun seos kiehahtaa, ota pois liedeltä ja sekoita joukkoon kylmä, paloiteltu voi.','When it boils, take off the heat and stir in the cold, cubed butter.'],['Kun jäähtynyt, pussita.','When cool, put into a piping bag.']]},{t:['Kasaus','Assembly'],i:[[2,'kpl','Savoyardikeksi / lasi','Ladyfingers per glass'],[null,'','Karamellipistaasi (Blankosta)','Caramel pistachios (from Blanko)']],s:[['Kostuta savoyardikeksi limoncelloliemessä, puolita ja laita lasipurkin pohjalle.','Dip a ladyfinger in the limoncello soak, halve it and put it in the bottom of the glass jar.'],['Pursota mascarponevaahtoa alle puoleenväliin lasia. Pursota pistaasikastiketta rinkulaksi, että osuu lasin reunoihin, ja sitten rinkulan sisälle.','Pipe mascarpone foam to just under halfway. Pipe a ring of pistachio sauce touching the glass edges, then inside the ring.'],['Ripottele kastikkeen päälle n. ½ rkl murskattua karamellipistaasia.','Sprinkle about ½ tbsp crushed caramel pistachios on the sauce.'],['Kostuta taas savoyardikeksi limoncellossa ja laita pistaasikerroksen päälle. Voit painaa keksiä hieman vaahtoon.','Dip another ladyfinger in limoncello and put it on the pistachio layer. You can press it slightly into the foam.'],['Pursota mascarponevaahtoa niin, että lasi jää vajaaksi n. ½–1 cm.','Pipe mascarpone foam so the glass stays about ½–1 cm short of full.'],['Kelmuta lasit ja laita kannelliseen muovipakkiin.','Cover the glasses with film and put them in a lidded plastic box.']]}]},
{id:'vegaaninen-jaatelo',c:'jaatelo',n:['Vegaaninen jäätelö (mustikka)','Vegan ice cream (blueberry)'],v:1,f:'2215',note:['N. 33 annosta. Cookie dough on vaihdettu mustikkakastikkeeseen: ½ reseptiin (0,5 l) 3 dl + 3 dl kastiketta.','About 33 portions. Cookie dough was replaced with blueberry sauce: for ½ recipe (0.5 l) 3 dl + 3 dl sauce.'],p:[{i:[[1,'l','Oddlygood vispi','Oddlygood whipping cream'],[640,'g','Kondensoitu kookosmaito (2 prk)','Condensed coconut milk (2 cans)'],[3,'dl','Oatly vaniljakastike','Oatly vanilla custard'],[4,'kpl','Vaniljatanko','Vanilla pod'],[84,'g','Glukoosisiirappi','Glucose syrup'],[12,'dl','Mustikkakastike (6 dl + 6 dl)','Blueberry sauce (6 dl + 6 dl)']],s:[['Sekoita keskenään kondensoitu kookosmaito, vaniljakastike, vaniljatangon siemenet ja glukoosisiirappi.','Mix the condensed coconut milk, vanilla custard, vanilla seeds and glucose syrup.'],['Vaahdota kauravispi kovaksi vaahdoksi.','Whip the oat cream to stiff peaks.'],['Vatkaa kauravispin joukkoon vaniljaseos.','Whisk the vanilla mix into the oat cream.'],['Lasipurkkiin: jäätelömassa → mustikkakastike → jäätelömassa → mustikkakastike. Pyöräytä varrastikulla pintaan kuviointia.','In a glass jar: ice cream → blueberry sauce → ice cream → blueberry sauce. Swirl a pattern on top with a skewer.'],['Kelmuta purkit ja pakasta.','Cover the jars with film and freeze.']]}]},
{id:'mustikkakastike',c:'kastike',n:['Mustikkakastike','Blueberry sauce'],v:1,f:'2216',p:[{i:[[1,'l','Pakastemustikoita (soseeseen)','Frozen blueberries (for the purée)'],[3,'dl','Sokeri','Sugar'],[252,'g','Glukoosisiirappi','Glucose syrup'],[6,'dl','Pakastemustikoita (kokonaisina)','Frozen blueberries (whole)']],s:[['Sulata isompi mustikkamäärä (1 l) kattilassa, poraa sauvasekoittimella ja paseeraa vielä pienisilmäisen siivilän läpi.','Melt the larger amount of blueberries (1 l) in a pot, blend with a stick blender and pass through a fine sieve.'],['Sekoita paseeratun mustikan joukkoon sokeri ja keittele paksuhkoksi.','Add the sugar to the purée and simmer until thickish.'],['Lisää glukoosisiirappi ja jatka vielä hetki keittämistä, kunnes rakenne on taas paksuuntunut.','Add the glucose syrup and keep cooking a little until it thickens again.'],['Kun rakenne on hyvä, lisää kokonaiset kohmeiset mustikat (6 dl) ja nosta pois levyltä.','When the texture is right, add the whole half-frozen blueberries (6 dl) and take off the heat.']]}]},
{id:'mustikkapaistos',c:'kakku',n:['Mustikkapaistos','Blueberry crumble bake'],v:1,f:'2217',note:['1× = 1 pieni Ikean metallivuoka. Paperissa käsin myös 3× ja 4× määrät.','1× = 1 small IKEA metal tin. Paper also has 3× and 4× amounts by hand.'],p:[{t:['Murutaikina','Crumble dough'],i:[[410,'g','Vehnäjauho','Wheat flour'],[204,'g','Sokeri','Sugar'],[null,'','Suolaa ripaus','Pinch of salt'],[240,'g','Eleplant kasvirasva','Eleplant plant fat']],s:[['Sulata rasva ja sekoita kuivien aineiden joukkoon.','Melt the fat and mix it into the dry ingredients.']]},{t:['Mustikkatäyte','Blueberry filling'],i:[[430,'g','Pakastemustikka','Frozen blueberries'],[13,'g','Perunajauho','Potato starch'],[80,'g','Sokeri','Sugar'],[0.5,'kpl','Sitruunan mehu, siivilöity','Lemon juice, strained']],s:[['Sekoita kaikki aineet mustikoiden joukkoon ja laita leivinpaperoidun vuoan pohjalle.','Mix everything into the blueberries and spread in a paper-lined tin.'],['Laita murutaikina päälle.','Top with the crumble dough.'],['Paista 160 °C n. 38–40 min.','Bake at 160 °C for about 38–40 min.']]}]},
{id:'vadelma-pastry-creme',c:'kreemi',n:['Vadelma pastry creme','Raspberry pastry cream'],f:'2218',note:['Paperissa käsin 2× määrät (vadelma ja maito 620 g, tarkista).','Paper has 2× amounts by hand (raspberry and milk 620 g, check).'],p:[{i:[[500,'g','Pakastevadelma, sulatettu','Frozen raspberries, thawed'],[310,'g','Maito (punainen)','Milk (full fat)'],[105,'g','Sokeri','Sugar'],[38,'g','Maizena','Cornflour'],[100,'g','Keltuainen','Egg yolk'],[14,'g','Voi, kylmä','Butter, cold'],[2,'g','Suola','Salt']],s:[['Soseuta ja siivilöi vadelmat, ota talteen 310 ml.','Purée and strain the raspberries; keep 310 ml.'],['Lämmitä maidosta 260 g ja sokeri höyryäväksi.','Heat 260 g of the milk with the sugar until steaming.'],['Vaahdota keltuaiset, maizena ja loput 50 g maitoa sekaisin.','Whisk the yolks, cornflour and the remaining 50 g milk.'],['Kaada kuuma maito varovasti joukkoon koko ajan sekoittaen. Lisää vadelmapyree.','Pour in the hot milk slowly while whisking. Add the raspberry purée.'],['Kuumenna seosta kattilassa, kunnes se paksuuntuu ja kiehahtaa.','Heat in a pot until it thickens and boils.'],['Ota pois levyltä, lisää voi ja suola. Anna jäähtyä, kipota ja laita kylmään.','Take off the heat, add the butter and salt. Let cool, put into containers and chill.']]}]},
{id:'jauhoton-suklaakakku',c:'kakku',n:['Jauhoton suklaakakku','Flourless chocolate cake'],f:'2219',note:['1× = 4 kakkua. 8 kakkuun tuplaa (2×).','1× = 4 cakes. For 8 cakes double it (2×).'],p:[{i:[[1200,'g','Tumma suklaa','Dark chocolate'],[900,'g','Voi','Butter'],[28,'kpl','Kananmuna','Egg'],[900,'g','Sokeri','Sugar'],[50,'g','Vaniljasokeri','Vanilla sugar'],[540,'g','Mantelijauhe','Almond flour']],s:[['Sulata voi ja suklaa.','Melt the butter and chocolate.'],['Vaahdota munat ja sokerit.','Whisk the eggs and sugars to a foam.'],['Sekoita voi-suklaaseos munavaahtoon ja lisää viimeiseksi mantelijauhe.','Mix the butter-chocolate into the egg foam and add the almond flour last.'],['Paista 150 °C n. 60 min.','Bake at 150 °C for about 60 min.']]}]},
{id:'suklaabrownie',c:'kakku',n:['Suklaabrownie','Chocolate brownie'],f:'2220',note:['1× = 5 pakkia. Pähkinät ovat valinnaisia. Paperin teipissä käsin pienempi määrä (2×-sarake, tarkista).','1× = 5 trays. Nuts are optional. The tape on the paper has a smaller amount by hand (check).'],p:[{i:[[3000,'g','Voi','Butter'],[1200,'g','Viikunahillo','Fig jam'],[1000,'g','Kaakaojauhe','Cocoa powder'],[60,'kpl','Kananmuna','Egg'],[7400,'g','Sokeri','Sugar'],[120,'g','Vaniljasokeri','Vanilla sugar'],[2600,'g','Vehnäjauho','Wheat flour'],[1750,'g','Pähkinöitä (valinnainen)','Nuts (optional)']],s:[['Sulata voi, lisää joukkoon viikunahillo sekä kaakaojauhe.','Melt the butter, add the fig jam and cocoa powder.'],['Sekoita munat ja sokerit nopeasti lapavatkaimella.','Mix the eggs and sugars quickly with the paddle.'],['Lisää voi-hillo-kaakaoseos.','Add the butter-jam-cocoa mix.'],['Lisää lopuksi vehnäjauhot ja sekoita nopeasti sekaisin.','Finally add the flour and mix quickly.'],['Jaa massa paperoituihin pakkeihin.','Divide into paper-lined trays.'],['Paista 165 °C n. 50 min.','Bake at 165 °C for about 50 min.']]}]},
{id:'runebergin-tortut',c:'leivos',n:['Runebergin tortut (gluteeniton)','Runeberg tarts (gluten-free)'],f:'2221',note:['N. 40 kpl. Paperissa käsin 50 kpl määrät (1,25×). Kostutusvedessä käsin 3,5 l vettä, 1,75 l sokeria ja 7 dl rommia (tarkista).','About 40 pcs. Paper has 50 pcs amounts by hand (1.25×). Soaking syrup has by hand 3.5 l water, 1.75 l sugar and 7 dl rum (check).'],p:[{t:['Taikina (n. 40 kpl)','Batter (about 40 pcs)'],i:[[1000,'g','Voi','Butter'],[950,'g','Sokeri','Sugar'],[10,'kpl','Kananmuna','Egg'],[640,'g','Vaalea gluteeniton jauho','Light gluten-free flour'],[350,'g','Mantelijauhe','Almond flour'],[350,'g','Gluteeniton korppujauho','Gluten-free breadcrumbs'],[22,'g','Leivinjauhe','Baking powder']],s:[['Vaahdota voi ja sokeri.','Cream the butter and sugar.'],['Lisää kananmunat vähän kerrallaan.','Add the eggs a little at a time.'],['Lisää lopuksi sekoitetut kuivat aineet.','Finally add the mixed dry ingredients.'],['Täytä hyvin voidellut vuoat vähän yli puolenvälin.','Fill well-greased moulds a little over halfway.'],['Paista 180 °C 15–20 min.','Bake at 180 °C for 15–20 min.']]},{t:['Kostutusvesi','Soaking syrup'],i:[[2.5,'l','Vesi','Water'],[1.25,'l','Sokeri','Sugar'],[5,'dl','Tumma rommi','Dark rum']],s:[['Kiehauta vesi ja sokeri, kunnes sokeri liukenee. Lisää rommi.','Boil the water and sugar until the sugar dissolves. Add the rum.'],['Kostuta tortut liemellä.','Soak the tarts with the syrup.']],gen:1}]},
{id:'blankon-vadelma-suklaakakku',c:'kakku',n:['Blankon vadelma-suklaakakku','Blanko raspberry chocolate cake'],f:'2222',note:['1× = 10 kpl 24 cm vuokaa, leivinpaperit pohjalle.','1× = 10 tins of 24 cm, baking paper on the bottom.'],p:[{t:['Kakkutaikina','Cake batter'],i:[[1500,'g','Voi','Butter'],[1000,'g','Tumma suklaa','Dark chocolate'],[30,'kpl','Kananmuna','Egg'],[2000,'g','Sokeri','Sugar'],[50,'ml','Vanilja-aromi','Vanilla extract'],[30,'g','Suola','Salt'],[1250,'g','Vehnäjauho','Wheat flour'],[500,'g','Kaakaojauhe','Cocoa powder'],[42,'g','Leivinjauhe','Baking powder'],[1500,'g','Kuohukerma','Whipping cream'],[550,'g','Maitosuklaahiput','Milk chocolate chips'],[200,'g','Maitosuklaa paiston jälkeen päälle','Milk chocolate on top after baking']],s:[['Sulata voi ja lisää suklaa joukkoon.','Melt the butter and add the chocolate.'],['Vaahdota munat ja sokeri kuohkeaksi vaahdoksi.','Whisk the eggs and sugar to a fluffy foam.'],['Lisää vanilja-aromi ja suola munavaahdon joukkoon.','Add the vanilla and salt to the egg foam.'],['Sekoita kuivat yhteen.','Mix the dry ingredients together.'],['Sekoita ensin munavaahtoon suklaa-voiseos, sitten kuivat aineet ja kerma vuorotellen. Lopuksi maitosuklaahiput.','First mix the chocolate-butter into the egg foam, then the dry ingredients and cream in turns. Finally the milk chocolate chips.']]},{t:['Vadelmat ja paisto','Raspberries and baking'],i:[[1750,'g','Pakastevadelmat','Frozen raspberries'],[70,'g','Perunajauho','Potato starch']],s:[['Sekoita vadelmat ja perunajauho yhteen.','Mix the raspberries and potato starch.'],['Jaa noin puolet kakkumassasta vuokiin ja päälle kaikki vadelmat. Loppu massa päälle.','Divide about half of the batter into the tins and put all the raspberries on top. Add the rest of the batter.'],['Paista 160 °C 38–40 min.','Bake at 160 °C for 38–40 min.'],['Paiston jälkeen loput maitosuklaat (200 g) päälle.','After baking, put the rest of the milk chocolate (200 g) on top.']]}]},
{id:'vegaaninen-sitruunajuustokakku',c:'kakku',n:['Vegaaninen sitruunajuustokakku','Vegan lemon cheesecake'],v:1,f:'2223',note:['30 kpl leivosta. Gluteeniton pohja.','30 pastries. Gluten-free base.'],p:[{t:['Pohja','Base'],i:[[300,'g','Gluteeniton digestivekeksi','Gluten-free digestive biscuits'],[150,'g','Margariini, sula','Margarine, melted']],s:[['Aja keksit muruksi ja sekoita margariinin kanssa.','Blitz the biscuits to crumbs and mix with the margarine.'],['Jaa massa runebergvuokiin ja painele reunoille ja pohjalle.','Divide into Runeberg moulds and press onto the sides and bottom.'],['Laita pakkaseen täytteen teon ajaksi.','Freeze while you make the filling.']]},{t:['Juustokakkumassa','Cheesecake filling'],i:[[1200,'g','Violife tuorejuusto','Violife cream cheese'],[180,'g','Kookoskerma','Coconut cream'],[300,'g','Tomusokeri','Icing sugar'],[600,'g','Cashewpähkinä, keitetty tai liotettu (punnaa ennen keittämistä)','Cashews, boiled or soaked (weigh before boiling)']],s:[['Aja pähkinät hienoksi muruksi.','Blitz the nuts to a fine crumb.'],['Lisää kookoskerma ja tomusokeri ja aja vielä tasaisemmaksi.','Add the coconut cream and icing sugar and blend smoother.'],['Lisää lopuksi tuorejuusto ja aja, kunnes kaikki on hyvin sekaisin.','Finally add the cream cheese and blend until well mixed.']]},{t:['Sitruunacurd','Lemon curd'],i:[[144,'g','Maizena','Cornflour'],[180,'g','Vesi','Water'],[600,'g','Eleplant','Eleplant'],[600,'g','Sokeri','Sugar'],[1020,'g','Sitruunamehu','Lemon juice'],[18,'kpl','Sitruunankuori','Lemon zest'],[600,'g','Kondensoitu kauramaito','Condensed oat milk'],[null,'','Kurkuma 3 mm (hyppysellinen)','Turmeric, a tiny pinch (3 mm)']],s:[['Sekoita maizena ja vesi.','Mix the cornflour and water.'],['Punnaa kaikki ainekset kattilaan ja kiehauta.','Weigh everything into a pot and bring to the boil.'],['Pussita, kun jäähtynyt.','Put into a piping bag when cool.']]},{t:['Kondensoitu kauramaito','Condensed oat milk'],i:[[1,'l','Kaurajuoma Barista','Oat drink Barista'],[340,'g','Sokeri','Sugar']],s:[['Kuumenna kattilassa kiehuvaksi ja anna kiehua, kunnes jäljellä 5–6 dl.','Bring to the boil in a pot and boil until 5–6 dl is left.'],['Anna jäähtyä jääkaappikylmäksi ennen käyttöä.','Cool to fridge temperature before use.']]},{t:['Kasaus','Assembly'],i:[],s:[['Kerrokset alhaalta ylös: pohja → juustomassa → sitruunacurd → juustomassa → sitruunacurd → juustomassa.','Layers from bottom to top: base → cheese filling → lemon curd → cheese filling → lemon curd → cheese filling.'],['Älä täytä ihan vuoan yläreunaan asti ja laita sitruunacurdia raitana väliin.','Do not fill to the very top, and pipe the lemon curd as a stripe between layers.']]}]},
{id:'pullataikina',c:'taikina',n:['Pullataikina ja bostontäyte','Sweet bun dough and Boston filling'],f:'2224',note:['1× = 1 l maitoa. Paperissa käsin 1,5 l ja 2 l määrät (2 l: kuivahiiva 80 g). Laskiaispullan paino 100 g.','1× = 1 l milk. Paper has 1.5 l and 2 l amounts by hand (2 l: dry yeast 80 g). Shrove bun weight 100 g.'],p:[{t:['Pullataikina (1 l)','Bun dough (1 l)'],i:[[1,'l','Maito','Milk'],[100,'g','Tuorehiiva','Fresh yeast'],[4,'dl','Sokeri','Sugar'],[4,'rkl','Kardemumma','Cardamom'],[4,'tl','Suola','Salt'],[2,'kpl','Kananmuna','Egg'],[2000,'g','Vehnäjauho (n.)','Wheat flour (about)'],[400,'g','Voi, huoneenlämpöinen','Butter, room temperature']],s:[['Lämmitä maito.','Warm the milk.'],['Lisää hiiva, sokeri, kardemumma, suola ja kananmuna.','Add the yeast, sugar, cardamom, salt and egg.'],['Lisää jauhot melkein kokonaan.','Add almost all of the flour.'],['Vaivaa nopeudella 1 n. 10 min.','Knead on speed 1 for about 10 min.'],['Lisää huoneenlämpöinen voi ja loput jauhot.','Add the room-temperature butter and the rest of the flour.'],['Vaivaa nopeudella 2 vielä n. 5 min.','Knead on speed 2 for about 5 more min.']]},{t:['Bostontäyte (½ l taikinaan)','Boston filling (for ½ l dough)'],i:[[200,'g','Pehmeä voi','Soft butter'],[2,'dl','Fariinisokeri','Brown sugar'],[null,'','Mantelijauhe','Almond flour'],[null,'','Kardemumma','Cardamom'],[null,'','Kaneli','Cinnamon']],s:[['Sekoita voi ja sokeri keskenään ja levitä kaulitun taikinan päälle.','Mix the butter and sugar and spread on the rolled-out dough.'],['Ripottele täytteen päälle reilusti mantelijauhetta ja mausta halutessasi kardemummalla ja kanelilla.','Sprinkle plenty of almond flour on top and season with cardamom and cinnamon if you like.']]}]},
{id:'vegaaninen-italialainen-marenki',c:'kreemi',n:['Vegaaninen italialainen marenki','Vegan Italian meringue'],v:1,f:'2225',p:[{t:['Redusoitu aquafaba','Reduced aquafaba'],i:[[1,'tlk','Kikherneitä (liemi)','Chickpeas (the liquid)']],s:[['Keitä yhden kikhernepurkin liemestä puolet pois.','Boil the liquid from one can of chickpeas down by half.'],['Anna jäähtyä ja käytä marengin valmistuksessa.','Let it cool and use it for the meringue.']]},{t:['Marenki','Meringue'],i:[[117,'g','Redusoitu aquafaba','Reduced aquafaba'],[0.6,'g','Viinikivi','Cream of tartar'],[200,'g','Sokeri','Sugar'],[60,'g','Vesi','Water']],s:[['Vaahdota aquafabaa ja viinikiveä, kunnes on selkeästi paksua vaahtoa.','Whisk the aquafaba and cream of tartar until clearly thick and foamy.'],['Keitä sokeriliemi 120 °C:een ja kaada vaahdon joukkoon samalla vaahdottaen.','Boil the sugar syrup to 120 °C and pour it into the foam while whisking.'],['Jatka vaahdottamista, kunnes padan reuna ei tunnu enää lämpimältä.','Keep whisking until the side of the bowl no longer feels warm.']]}]},
{id:'vegaaninen-omenakakku',c:'kakku',n:['Vegaaninen omenakakku','Vegan apple cake'],v:1,f:'2226',note:['1× = 6 kpl M-kokoisia silikonivuokia. Paperissa käsin 2×, 1,5× ja 10 kpl määrät.','1× = 6 medium silicone moulds. Paper has 2×, 1.5× and 10-mould amounts by hand.'],p:[{t:['Omenat','Apples'],i:[[27,'kpl','Omena (Pink Lady)','Apple (Pink Lady)'],[450,'g','Margariini, sula','Margarine, melted'],[126,'g','Kaneli','Cinnamon'],[315,'g','Fariinisokeri','Brown sugar'],[384,'g','Sokeri','Sugar']],s:[['Leikkaa omena ohuiksi siivuiksi ja sekoita joukkoon loput ainekset.','Slice the apples thinly and mix in the rest of the ingredients.'],['Jaa vuokiin, peitä leivinpaperilla ja paista 170 °C 1 tunti.','Divide into the moulds, cover with baking paper and bake at 170 °C for 1 hour.']]},{t:['Taikina','Batter'],i:[[675,'g','Margariini, sula','Margarine, melted'],[456,'g','Fariinisokeri','Brown sugar'],[876,'g','Vehnäjauho','Wheat flour'],[1.6,'tl','Suola','Salt'],[1,'rkl','Leivinjauhe','Baking powder'],[1,'rkl','Kardemumma','Cardamom'],[504,'g','Kauramaito','Oat milk']],s:[['Kun omenoiden paistoa on jäljellä n. 10 min, tee taikina, jotta se on helppo levittää omenoiden päälle.','When the apples have about 10 min left, make the batter so it is easy to spread on the apples.'],['Sekoita margariini ja fariinisokeri yhteen, lisää kuivien joukkoon ja lopuksi kauramaito.','Mix the margarine and brown sugar, add to the dry ingredients and finally the oat milk.']]},{t:['Stroisseli','Streusel'],i:[[228,'g','Eleplant, ruskistettu','Eleplant, browned'],[336,'g','Vehnäjauho','Wheat flour'],[246,'g','Fariinisokeri','Brown sugar'],[108,'g','Sokeri','Sugar'],[1,'rkl','Kaneli','Cinnamon'],[0.75,'tl','Suola','Salt']],s:[['Punnaa kuivat aineet sekaisin ja lisää ruskistettu Eleplant.','Weigh the dry ingredients together and add the browned Eleplant.'],['Kun omenat tulevat uunista, jaa taikina omenoiden päälle ja murusta stroisseli taikinan päälle.','When the apples come out, spread the batter on them and crumble the streusel on top.'],['Jatka paistoa vielä 170 °C 15 min.','Bake for 15 more min at 170 °C.']]}]},
{id:'swiss-marenki',c:'kreemi',n:['Swiss marenki','Swiss meringue'],f:'2227',note:['Isompi erä on 4× (680 g valkuaisia).','The bigger batch is 4× (680 g egg whites).'],p:[{i:[[170,'g','Valkuainen','Egg white'],[225,'g','Sokeri','Sugar'],[0.125,'tl','Suola (1/8 tl)','Salt (1/8 tsp)'],[0.25,'tl','Viinikivi','Cream of tartar']],s:[['Kuumenna vesihauteessa 79 asteiseksi.','Heat over a water bath to 79 °C.'],['Vaahdota, pussita ja pakasta.','Whisk, put into piping bags and freeze.']]}]},
{id:'pistaasikeksit-vg',c:'leivos',n:['Pistaasikeksit (vegaani, gluteeniton)','Pistachio cookies (vegan, gluten-free)'],v:1,f:'2228',note:['N. 40 kpl. Paperissa käsin 2× ja 3× määrät.','About 40 pcs. Paper has 2× and 3× amounts by hand.'],p:[{i:[[150,'g','Margariini','Margarine'],[85,'g','Sokeri','Sugar'],[105,'g','Fariinisokeri','Brown sugar'],[1,'tl','Vanilja-aromi','Vanilla extract'],[1,'tl','Suola','Salt'],[1,'rkl','Pellavansiemenrouhe','Ground flaxseed'],[52.5,'g','Vesi, kylmä','Water, cold'],[260,'g','Vaalea gluteeniton jauho','Light gluten-free flour'],[25,'g','Mantelijauhe','Almond flour'],[1,'dl','Karamellipistaasi','Caramel pistachios']],s:[['Vaahdota margariini, sokerit, vanilja ja suola kuohkeaksi.','Cream the margarine, sugars, vanilla and salt until fluffy.'],['Sekoita pellavansiemenrouhe ja kylmä vesi yhteen ja anna tekeytyä vaahdon muodostumisen ajan.','Mix the flaxseed and cold water and let it rest while the foam forms.'],['Lisää pellavaseos joukkoon ja vaahdota vielä hetki.','Add the flax mix and whisk a little more.'],['Kutteroi pistaasit ja lisää jauhojen joukkoon.','Chop the pistachios in the cutter and add to the flours.'],['Sekoita kuivat margariinivaahdon joukkoon.','Mix the dry ingredients into the margarine foam.'],['Punnaa taikinasta 17–18 g palloja.','Weigh 17–18 g balls.'],['Paista silikonimaton päällä, litistä ennen paistoa. 180 °C 3 min.','Bake on a silicone mat, flatten before baking. 180 °C for 3 min.']]}]},
{id:'blankon-mustikkapiirakka',c:'kakku',n:['Blankon mustikkapiirakka','Blanko blueberry pie'],v:1,f:'2229',note:['1× = 10 piirakkaa. 6 kpl = 0,6× ja 4 kpl = 0,4×. Mustikka 6 l = n. 3,5 kg. Muruseos on puolet taikinasta (10 kpl: 4188 g).','1× = 10 pies. 6 pcs = 0.6× and 4 pcs = 0.4×. Blueberries 6 l = about 3.5 kg. The crumble is half of the dough (10 pcs: 4188 g).'],p:[{i:[[4100,'g','Vehnäjauho','Wheat flour'],[2040,'g','Sokeri','Sugar'],[140,'g','Sooda','Baking soda'],[null,'','Suolaa ripaus','Pinch of salt'],[80,'g','Leivinjauhe','Baking powder'],[1875,'g','Keiju margariini, sulatettu','Keiju margarine, melted'],[2320,'g','Kaurafraiche','Oat crème fraîche'],[3500,'g','Mustikka (6 l)','Blueberries (6 l)'],[130,'g','Perunajauho','Potato starch']],s:[['Mittaa kuivat aineet pataan. Sekoita hetken aikaa.','Measure the dry ingredients into the bowl. Mix for a moment.'],['Lisää sulatettu margariini ja sekoita nopeasti murumaiseksi massaksi.','Add the melted margarine and mix quickly to a crumbly mass.'],['Ota massasta puolet pois eri astiaan (10 kpl erässä 4188 g). Tämä on piirakan päälle tuleva muruseos.','Take half of the mass into another bowl (4188 g for 10 pcs). This is the crumble for the top.'],['Lisää kaurafraiche padassa olevaan massaan ja sekoita hyvin. Tämä on piirakan pohja.','Add the oat crème fraîche to the mass left in the bowl and mix well. This is the pie base.'],['Annostele taikina vuokiin.','Portion the dough into the tins.'],['Huom! Esipaista pohjia n. 20–30 min 175 °C, kunnes ovat kypsiä.','Note! Pre-bake the bases about 20–30 min at 175 °C until cooked.'],['Lisää mustikat (sekoitettuna perunajauhoon) ja viimeiseksi muruseos mustikoiden päälle.','Add the blueberries (mixed with the potato starch) and finally the crumble on top.'],['Paista 160 °C n. 45–55 min. Käännä paiston puolessavälissä.','Bake at 160 °C for about 45–55 min. Turn halfway through.']]}]},
{id:'kristallisuklaa',c:'koriste',n:['Kristallisuklaa','Crystallised chocolate'],f:'2230',note:['Tästä määrästä tulee pieni vetarikippo. Voit käyttää haluamaasi suklaata: maito, tumma, valko, karamelli tai ruby.','This makes a small Vetari bowl. You can use any chocolate: milk, dark, white, caramel or ruby.'],p:[{i:[[150,'g','Vesi','Water'],[255,'g','Sokeri','Sugar'],[150,'g','Suklaa','Chocolate']],s:[['Sulata suklaa mikrossa.','Melt the chocolate in the microwave.'],['Keitä sokeri ja vesi 140 °C:een.','Boil the sugar and water to 140 °C.'],['Kaada sokerivesi suklaan joukkoon ja sekoita pallovispilällä voimalla, kunnes murua.','Pour the syrup into the chocolate and stir hard with a ball whisk until it turns to crumbs.'],['Kaada pellille ja anna jäähtyä.','Pour onto a tray and let cool.']]}]},
{id:'gluteeniton-pulla',c:'taikina',n:['Gluteeniton pulla ja pistaasitäyte','Gluten-free bun and pistachio filling'],f:'2231',p:[{t:['Gluteeniton pullataikina','Gluten-free bun dough'],i:[[175,'g','Gluteeniton jauhoseos (Caputo), tarvittaessa lisää','Gluten-free flour mix (Caputo), more if needed'],[0.5,'tl','Ksantaani','Xanthan gum'],[1,'rkl','Sokeri','Sugar'],[1.5,'tl','Leivinjauhe','Baking powder'],[0.5,'tl','Suola','Salt'],[1,'rkl','Kardemumma','Cardamom'],[245,'g','Turkkilainen jugurtti','Turkish yogurt'],[1,'kpl','Kananmuna','Egg'],[1,'tl','Vanilja-aromi','Vanilla extract']],s:[['Sekoita kuivat aineet yhteen ja lisää loput sekaan.','Mix the dry ingredients and add the rest.'],['Sekoita lapavatkaimella, kunnes muistuttaa taikinaa. Jauhoja saattaa joutua lisäämään.','Mix with the paddle until it looks like dough. You may need to add more flour.'],['Kaulitse levyksi ja täytä mieluisalla täytteellä. Taikinan kannattaa olla kylmää, se helpottaa käsittelyä.','Roll into a sheet and fill with the filling you like. Cold dough is easier to handle.'],['Paista 175 °C n. 15 min pullien koosta riippuen.','Bake at 175 °C for about 15 min depending on bun size.']]},{t:['Pistaasitäyte','Pistachio filling'],i:[[200,'g','Pistaasit','Pistachios'],[130,'g','Voi','Butter'],[1,'dl','Sokeri','Sugar'],[1,'rkl','Vaniljasokeri','Vanilla sugar'],[null,'','Suolaa ripaus','Pinch of salt'],[1,'rkl','Maizena','Cornflour']],s:[['Aja kaikki aineet tasaiseksi tahnaksi (kutteri tai sauvasekoitin).','Blend everything to a smooth paste (cutter or stick blender).']]}]},
{id:'valkosuklaa-salmiakkikakku',c:'kakku',n:['Paahdettu valkosuklaa-salmiakkikakku','Toasted white chocolate and salmiakki cake'],f:'2232',note:['15 annosta. Paperissa näkyy vain ainekset: valmistusohje on kirjoitettu yleisen tavan mukaan, tarkista.','15 portions. Only the ingredients show on the paper: the method is written the usual way, check.'],p:[{t:['Pohja','Base'],i:[[200,'g','Kaura- tai digestivekeksit','Oat or digestive biscuits'],[100,'g','Voi, sulatettu','Butter, melted']],s:[['Murskaa keksit ja sekoita sulan voin kanssa.','Crush the biscuits and mix with the melted butter.'],['Painele irtopohjavuoan pohjalle ja laita jääkaappiin.','Press into the bottom of a springform tin and chill.']],gen:1},{t:['Valkosuklaatäyte','White chocolate filling'],i:[[200,'g','Valkosuklaa (paahdettu)','White chocolate (toasted)'],[2,'dl','Kuohukerma','Whipping cream'],[3,'kpl','Liivatelehti','Gelatine sheet'],[125,'g','Maitorahka (½ tlk)','Quark (½ tub)'],[200,'g','Maustamaton tuorejuusto','Plain cream cheese'],[1,'dl','Sokeri','Sugar'],[2,'rkl','Kiehuvaa vettä','Boiling water']],s:[['Paahda valkosuklaa uunissa 120 °C, sekoita 10 min välein, kunnes kullanruskea. Anna jäähtyä hieman.','Toast the white chocolate in the oven at 120 °C, stirring every 10 min, until golden. Let it cool a little.'],['Liota liivatteet kylmässä vedessä.','Soak the gelatine in cold water.'],['Sekoita rahka, tuorejuusto ja sokeri. Vatkaa kerma vaahdoksi.','Mix the quark, cream cheese and sugar. Whip the cream.'],['Purista liivatteet ja liuota kiehuvaan veteen. Lisää rahkaseokseen koko ajan sekoittaen, sitten suklaa.','Squeeze the gelatine and dissolve it in the boiling water. Stir it into the quark mix, then add the chocolate.'],['Kääntele kermavaahto joukkoon ja kaada pohjan päälle. Anna hyytyä jääkaapissa.','Fold in the whipped cream and pour onto the base. Let set in the fridge.']],gen:1},{t:['Salmiakkitäyte','Salmiakki filling'],i:[[4,'kpl','Liivatelehti','Gelatine sheet'],[125,'g','Maitorahka (½ tlk)','Quark (½ tub)'],[1,'dl','Sokeri','Sugar'],[200,'g','Maustamaton tuorejuusto','Plain cream cheese'],[1.5,'dl','Apteekkarin salmiakki mixeri','Apteekkari salmiakki mixer'],[2,'dl','Kuohukerma','Whipping cream']],s:[['Liota liivatteet kylmässä vedessä.','Soak the gelatine in cold water.'],['Sekoita rahka, sokeri ja tuorejuusto. Lämmitä osa mixeristä ja liuota puristetut liivatteet siihen. Lisää loput mixeristä.','Mix the quark, sugar and cream cheese. Warm part of the mixer and dissolve the squeezed gelatine in it. Add the rest of the mixer.'],['Sekoita mixeri rahkaseokseen ja kääntele joukkoon vaahdotettu kerma.','Stir the mixer into the quark mix and fold in the whipped cream.'],['Kaada hyytyneen valkosuklaakerroksen päälle ja anna hyytyä yön yli jääkaapissa.','Pour onto the set white chocolate layer and let set overnight in the fridge.']],gen:1}]},
{id:'valkosuklaacookies',c:'leivos',n:['Valkosuklaacookies','White chocolate cookies'],f:'2233',note:['Taikinapötkö 800 g, keksi 80 g. Teipissä käsin pienempi erä: 5 pötköä (1000 g sokeria jne.) ja 4 pötköä (800 g).','Dough log 800 g, cookie 80 g. The tape has a smaller batch by hand: 5 logs (1000 g sugar etc.) and 4 logs (800 g).'],p:[{i:[[4000,'g','Sokeri','Sugar'],[4000,'g','Voi','Butter'],[5600,'g','Vehnäjauho','Wheat flour'],[600,'g','Hasselpähkinärouhe','Chopped hazelnuts'],[600,'g','Vaalea siirappi','Light syrup'],[80,'g','Ruokasooda','Baking soda'],[4,'kpl','Kananmuna','Egg'],[600,'g','Valkosuklaarouhe','Chopped white chocolate']],s:[['Vatkaa voita ja sokeria lapavatkaimella, kunnes voi hieman pehmenee.','Beat the butter and sugar with the paddle until the butter softens a little.'],['Sekoita loput raaka-aineet keskenään.','Mix the rest of the ingredients together.'],['Lisää kuivat aineet voi-sokerimassaan.','Add the dry ingredients to the butter-sugar mass.'],['Punnitse taikinasta 800 g paloja, pyörittele pötköiksi ja kääri leivinpaperiin.','Weigh 800 g pieces, roll into logs and wrap in baking paper.'],['Laita taikinapötköt pakkaseen.','Freeze the logs.'],['Leikkaa pötköstä 80 g paloja ja painele keksit paperoiduille ja voidelluille pelleille.','Cut 80 g pieces and press them onto lined, greased trays.'],['Paista 180 °C 25 min.','Bake at 180 °C for 25 min.']]}]},
{id:'karpalotorttu-tayte',c:'kastike',n:['Karpalotorttutäyte','Cranberry tart filling'],f:'2234',note:['1× = 1 kpl. 2 kpl:een tuplaa.','1× = 1 batch. For 2 batches double it.'],p:[{i:[[340,'g','Karpalot','Cranberries'],[250,'g','Sokeri (keittoon)','Sugar (for cooking)'],[0.5,'dl','Vesi','Water'],[3,'kpl','Kananmuna','Egg'],[2,'kpl','Keltuainen','Egg yolk'],[null,'','Suolaa ripaus','Pinch of salt'],[125,'g','Sokeri (loput)','Sugar (the rest)'],[1.1,'dl','Sitruunamehu','Lemon juice'],[55,'g','Voi','Butter']],s:[['Mittaa kattilaan karpalot, isompi määrä sokerista (250 g) ja 0,5 dl vettä.','Put the cranberries, the bigger amount of sugar (250 g) and 0.5 dl water in a pot.'],['Keitä n. 15 min, kunnes suurin osa karpaloista on poksahtanut ja seos on hiukan keittynyt kasaan. Paseeraa.','Cook about 15 min until most berries have popped and it has reduced a little. Pass through a sieve.'],['Mittaa kattilaan karpalosose, munat, keltuaiset, suola, loppu sokeri ja sitruunamehu.','Put the cranberry purée, eggs, yolks, salt, the rest of the sugar and lemon juice in a pot.'],['Keitä miedolla lämmöllä, kunnes massa on selvästi paksuuntunut (n. 10 min). Paseeraa vielä kerran.','Cook on low heat until clearly thick (about 10 min). Pass through a sieve again.'],['Lisää voi pienissä paloissa ja sekoita hyvin.','Add the butter in small pieces and mix well.'],['Kaada esipaistetuille torttupohjille ja anna hyytyä hetki huoneenlämmössä ennen pakastamista.','Pour into pre-baked tart shells and let set a moment at room temperature before freezing.']]}]},
{id:'suklaacookies',c:'leivos',n:['Suklaacookies','Chocolate cookies'],f:'2235',note:['Taikinapötkö 800 g, keksi 80 g. Teipissä käsin pienempi erä: n. 6 pötköä (666 g sokeria jne.) ja 4 pötköä (400 g).','Dough log 800 g, cookie 80 g. The tape has a smaller batch by hand: about 6 logs (666 g sugar etc.) and 4 logs (400 g).'],p:[{i:[[2000,'g','Fariinisokeri','Brown sugar'],[2000,'g','Sokeri','Sugar'],[4000,'g','Voi','Butter'],[5000,'g','Vehnäjauho','Wheat flour'],[600,'g','Hasselpähkinärouhe','Chopped hazelnuts'],[600,'g','Kaakaojauhe','Cocoa powder'],[600,'g','Tumma siirappi','Dark syrup'],[4,'kpl','Kananmuna','Egg'],[80,'g','Ruokasooda','Baking soda'],[600,'g','Suklaarouhe','Chopped chocolate']],s:[['Vatkaa voita ja sokereita lapavatkaimella, kunnes voi hieman pehmenee.','Beat the butter and sugars with the paddle until the butter softens a little.'],['Sekoita loput raaka-aineet keskenään.','Mix the rest of the ingredients together.'],['Lisää kuivat aineet voi-sokerimassaan.','Add the dry ingredients to the butter-sugar mass.'],['Punnitse taikinasta 800 g paloja, pyörittele pötköiksi ja kääri leivinpaperiin.','Weigh 800 g pieces, roll into logs and wrap in baking paper.'],['Laita taikinapötköt pakkaseen.','Freeze the logs.'],['Leikkaa pötköstä 80 g paloja ja painele keksit paperoiduille ja voidelluille pelleille.','Cut 80 g pieces and press them onto lined, greased trays.'],['Paista 180 °C 25 min.','Bake at 180 °C for 25 min.']]}]},
{id:'rocky-road-brownie',c:'kakku',n:['Rocky Road Brownie','Rocky road brownie'],f:'2236',note:['1× = 1/1 GN. Paperissa myös 2 GN ja 4 × 1/1 GN määrät.','1× = 1/1 GN. Paper also has 2 GN and 4 × 1/1 GN amounts.'],p:[{t:['Brownie (1/1 GN)','Brownie (1/1 GN)'],i:[[300,'g','Tumma suklaa','Dark chocolate'],[100,'g','Voi','Butter'],[1,'dl','Rypsiöljy','Rapeseed oil'],[4,'kpl','Kananmuna','Egg'],[2,'dl','Sokeri','Sugar'],[2,'dl','Fariinisokeri','Brown sugar'],[30,'g','Kaakaojauhe','Cocoa powder'],[200,'g','Vehnäjauho','Wheat flour'],[1,'tl','Leivinjauhe','Baking powder'],[1,'tl','Vaniljasokeri','Vanilla sugar'],[0.25,'tl','Suola','Salt'],[null,'','Valkosuklaarouhe, kuivattu karpalo, pähkinä ym.','Chopped white chocolate, dried cranberry, nuts etc.']],s:[['Sulata suklaa ja voi ja lisää öljy joukkoon.','Melt the chocolate and butter and add the oil.'],['Vaahdota munat ja sokerit.','Whisk the eggs and sugars to a foam.'],['Sekoita kuivat aineet keskenään.','Mix the dry ingredients.'],['Sekoita suklaaseos munavaahtoon.','Mix the chocolate into the egg foam.'],['Lisää kuivat aineet ja lopuksi mahdolliset rouheet.','Add the dry ingredients and finally any chopped add-ins.'],['Paista 150 °C n. 15 min (saa jäädä sisältä tahmeaksi).','Bake at 150 °C for about 15 min (may stay sticky inside).']]},{t:['Maapähkinävoikuorrute (1/1 GN)','Peanut butter topping (1/1 GN)'],i:[[680,'g','Valkosuklaa','White chocolate'],[1.2,'dl','Maapähkinävoi','Peanut butter'],[null,'','Vaahtokarkit','Marshmallows']],s:[['Sulata suklaa ja maapähkinävoi ja lisää vaahtokarkit.','Melt the chocolate and peanut butter and add the marshmallows.']]}]},
{id:'rahkatayte',c:'kreemi',n:['Rahkatäyte','Quark filling'],f:'2238',note:['1× = 4 × 1/1 GN. Käsin: 1 kpl 26 cm vuokaan maitorahka 415 g, kananmuna 2 kpl, sokeri 85 g, vaniljakreemijauhe 54 g, vaniljasokeri.','1× = 4 × 1/1 GN. By hand: for one 26 cm tin quark 415 g, egg 2 pcs, sugar 85 g, vanilla custard powder 54 g, vanilla sugar.'],p:[{i:[[5000,'g','Maitorahka','Quark'],[20,'kpl','Kananmuna','Egg'],[1000,'g','Sokeri','Sugar'],[650,'g','Vaniljakreemijauhe','Vanilla custard powder']],s:[['Sekoita kaikki raaka-aineet keskenään.','Mix all ingredients together.']]}]},
{id:'mantelitayte',c:'kreemi',n:['Mantelitäyte (laskiaispulliin)','Almond filling (for Shrove buns)'],f:'2238',p:[{i:[[300,'g','Voi','Butter'],[300,'g','Tomusokeri','Icing sugar'],[500,'g','Mantelijauhe','Almond flour'],[null,'','Kerma tarvittaessa','Cream if needed']],s:[['Sekoita kaikki raaka-aineet keskenään ja notkista massaa tarvittaessa kermalla.','Mix everything together and loosen with cream if needed.']]}]},
{id:'toscakuorrute',c:'koriste',n:['Toscakuorrute ja appelsiinitoscakuorrute','Tosca topping and orange tosca topping'],f:'2238',p:[{t:['Toscakuorrute','Tosca topping'],i:[[2200,'g','Voi','Butter'],[2200,'g','Sokeri','Sugar'],[2,'l','Kerma','Cream'],[460,'g','Siirappi','Syrup'],[2200,'g','Mantelilastu','Flaked almonds']],s:[['Punnitse kaikki raaka-aineet kattilaan ja sekoittele, kunnes voi sulaa.','Weigh everything into a pot and stir until the butter melts.']]},{t:['Appelsiinitoscakuorrute','Orange tosca topping'],i:[[450,'g','Voi','Butter'],[450,'g','Sokeri','Sugar'],[400,'g','Appelsiinimarmeladi','Orange marmalade'],[90,'g','Vehnäjauho','Wheat flour'],[450,'g','Mantelilastu','Flaked almonds'],[1,'dl','Appelsiinimehu','Orange juice']],s:[['Punnitse kaikki raaka-aineet kattilaan ja sekoittele, kunnes voi sulaa.','Weigh everything into a pot and stir until the butter melts.']]}]},
{id:'ahvenanmaan-pannukakku',c:'kakku',n:['Ahvenanmaan pannukakku','Åland pancake'],v:1,f:'2239',note:['Riisipuurosta tulee 2 GN pannaria. Pannaritaikina 1× = 1 GN (4 GN = 4×).','The rice porridge makes 2 GN of pancake. Pancake batter 1× = 1 GN (4 GN = 4×).'],p:[{t:['Riisipuuro','Rice porridge'],i:[[2,'tl','Suola','Salt'],[4,'dl','Puuroriisi','Porridge rice'],[2,'l','Vaniljasoijamaito','Vanilla soy milk']],s:[['Punnaa syvään 1/2 GN vuokaan.','Weigh into a deep 1/2 GN tray.'],['Höyrypaista 120 °C 1 tunti. Sekoittele välillä.','Steam-bake at 120 °C for 1 hour. Stir now and then.']]},{t:['Pannaritaikina (1 GN)','Pancake batter (1 GN)'],i:[[2,'l','Vaniljasoijamaito','Vanilla soy milk'],[970,'g','Kypsää riisipuuroa','Cooked rice porridge'],[2,'dl','Flora Culinesse','Flora Culinesse'],[170,'g','Sokeri','Sugar'],[2,'dl','Kaurajugurtti','Oat yogurt'],[1,'rkl','Kardemumma','Cardamom'],[1.5,'tl','Suola','Salt'],[585,'g','Vehnäjauho','Wheat flour']],s:[['Sekoita puuron joukkoon ensin kaikki muut paitsi maito ja jauhot.','First mix everything except the milk and flour into the porridge.'],['Lisää jauhot ja maito vuorotellen taikinaan.','Add the flour and milk in turns.'],['Kaada leivinpaperoituun pakkiin. Laita vielä taikinan pinnalle leivinpaperi.','Pour into a paper-lined tray. Put baking paper on top of the batter too.'],['Paista 170 °C n. 60 min. Poista paperi puolessa välissä paistoa.','Bake at 170 °C for about 60 min. Remove the top paper halfway.']]}]},
{id:'punajuuri-velvet',c:'kakku',n:['Punajuuri Velvet (gluteeniton)','Beetroot velvet cake (gluten-free)'],f:'2240',note:['1× = 1 kakku. 3 kakkuun 3×.','1× = 1 cake. For 3 cakes 3×.'],p:[{t:['Kakkupohja','Cake'],i:[[375,'g','Kypsä punajuuri','Cooked beetroot'],[112,'ml','Maito','Milk'],[1,'rkl','Sitruunamehu','Lemon juice'],[2.25,'tl','Omenaviinietikka','Apple cider vinegar'],[1.5,'tl','Vanilja-aromi','Vanilla extract'],[190,'g','Voi','Butter'],[3,'kpl','Kananmuna','Egg'],[375,'g','Gluteeniton jauho','Gluten-free flour'],[225,'g','Sokeri','Sugar'],[1.5,'rkl','Kaakaojauhe','Cocoa powder'],[1,'rkl','Leivinjauhe','Baking powder']],s:[['Sekoita maito ja sitruunamehu, anna tekeytyä muiden aineiden mittaamisen ajan.','Mix the milk and lemon juice and let it rest while you measure the rest.'],['Pilko punajuuri pienemmiksi paloiksi. Soseuta se maidon, etikan ja vanilja-aromin kanssa.','Cut the beetroot into smaller pieces. Purée it with the milk, vinegar and vanilla.'],['Lisää voi seokseen ja soseuta lisää. Lisää sitten munat ja lopuksi kuivat aineet käsin sekoittaen.','Add the butter and blend more. Then add the eggs and finally the dry ingredients, mixing by hand.'],['Paista yhden kakun kerrokset 2 vuoassa.','Bake the layers of one cake in 2 tins.'],['Paista 175 °C n. 25–30 min. Tikuta ja tarkista kypsyys.','Bake at 175 °C for about 25–30 min. Test with a skewer.']]},{t:['Täyte ja kuorrute','Filling and frosting'],i:[[300,'g','Mascarpone','Mascarpone'],[280,'g','Tomusokeri','Icing sugar'],[2,'tl','Vanilja-aromi','Vanilla extract'],[null,'','Vaniljasokerilla makeutettu maito (kostutukseen)','Milk sweetened with vanilla sugar (for soaking)']],s:[['Vaahdota vispilällä kaikki aineet tiukaksi vaahdoksi.','Whisk everything to a firm cream.'],['Kostuta kakkupohjat vaniljasokerilla makeutetulla maidolla ja täytä ja kuorruta mascarponekuorrutteella.','Soak the layers with vanilla-sweetened milk, then fill and frost with the mascarpone cream.'],['Anna kakun vetäytyä kylmässä ennen leikkaamista.','Let the cake set in the cold before cutting.']]}]},
{id:'pizzataikina-hapanjuuri',c:'taikina',n:['Pizzataikina hapanjuurella','Sourdough pizza dough'],v:1,f:'2241',note:['1× = 20 kpl (pala 280 g). 30 kpl = 1,5× ja 40 kpl = 2×.','1× = 20 pcs (280 g each). 30 pcs = 1.5× and 40 pcs = 2×.'],p:[{i:[[2000,'g','Vesi (27 °C)','Water (27 °C)'],[600,'g','Aktiivinen juuri','Active sourdough starter'],[250,'g','Oliiviöljy','Olive oil'],[1500,'g','Caputo 00 -jauho','Caputo 00 flour'],[1500,'g','Vehnäjauho','Wheat flour'],[80,'g','Atlantin karkea merisuola','Coarse Atlantic sea salt'],[2,'dl','Oliiviöljy taitteluvaiheeseen','Olive oil for the folding stage']],s:[['Sekoita aktiivinen juuri ensin veteen.','Mix the active starter into the water first.'],['Lisää öljy, jauhot ja suola. Sekoita taikina.','Add the oil, flours and salt. Mix the dough.'],['Anna taikinan levätä 30 min (autolyysi).','Rest the dough 30 min (autolysis).'],['Lisää öljy, taittele ja anna levätä 15 min.','Add the oil, fold and rest 15 min.'],['Taittele ja anna levätä 15 min. Toista vielä kerran (15 min).','Fold and rest 15 min. Repeat once more (15 min).'],['Taittele ja anna levätä 60 min.','Fold and rest 60 min.'],['Paloittele taikina 280 g paloiksi ja muotoile palat nipistelemällä tiiviiksi palloiksi.','Divide into 280 g pieces and pinch them into tight balls.'],['Laita pallot öljyttyihin kannellisiin pitsapakkeihin tuorekelmulla peitettynä.','Put the balls in oiled lidded pizza boxes covered with cling film.'],['Anna taikinapallojen levätä kylmässä (2–4 °C) vähintään seuraavaan päivään.','Let the balls rest in the cold (2–4 °C) at least until the next day.'],['Ota pallot huoneenlämpöön n. 2 tuntia ennen paistamista. Taikinan pitää olla n. 20 °C ennen muotoilua ja täyttämistä.','Take the balls to room temperature about 2 hours before baking. The dough should be about 20 °C before shaping and topping.'],['Paista pitsauunissa 350 °C 2–3 min.','Bake in the pizza oven at 350 °C for 2–3 min.']]}]},
{id:'gluteeniton-briossisampyla',c:'taikina',n:['Gluteeniton briossisämpylä','Gluten-free brioche bun'],v:1,f:'2242',note:['N. 9 sämpylää (pala 130 g). Käsin 2× määrät (= 8 kpl, tarkista). Lämmitä kauramaito vähän.','About 9 buns (130 g each). Hand-written 2× amounts (= 8 pcs, check). Warm the oat milk a little.'],p:[{i:[[500,'g','Gluteeniton Caputo-jauho','Gluten-free Caputo flour'],[20,'g','Psyllium','Psyllium'],[90,'g','Sokeri','Sugar'],[14,'g','Leivinjauhe','Baking powder'],[24,'g','Kuivahiiva','Dry yeast'],[18,'g','Suola','Salt'],[300,'ml','Kauramaito, vähän lämmitetty','Oat milk, slightly warmed'],[170,'g','Margariini','Margarine'],[6,'g','No Egg','No Egg (egg replacer)'],[60,'ml','Vesi','Water']],s:[['Ota margariini huoneenlämpöön.','Bring the margarine to room temperature.'],['Sekoita kuivat aineet keskenään.','Mix the dry ingredients.'],['Vaahdota hiukan No Egg- ja vesiseosta.','Whisk the No Egg and water a little.'],['Lisää kuiviin maito, margariini ja No Egg -seos.','Add the milk, margarine and No Egg mix to the dry ingredients.'],['Vatkaa lapavatkaimella ainakin 5 min reilulla nopeudella.','Beat with the paddle for at least 5 min at good speed.'],['Kumoa taikina kippoon ja anna nousta 2 tuntia peitettynä.','Turn the dough into a bowl and let it rise 2 hours covered.'],['Laita astia kylmään ja leivo seuraavana päivänä.','Put the bowl in the cold and bake the next day.'],['Palapaino 130 g. Painele sämpylöitä ennen nostatusta, nostata höyryssä.','Piece weight 130 g. Press the buns before proving; prove in steam.'],['Paista 175 °C n. 15 min.','Bake at 175 °C for about 15 min.']]}]},
{id:'porkkanakakku-gtv',c:'kakku',n:['Porkkanakakku (gluteeniton ja vegaani)','Carrot cake (gluten-free and vegan)'],v:1,f:'2243',note:['1× = 1/1 GN. 2 ja 4 kpl 1/1 GN = 2× ja 4×.','1× = 1/1 GN. 2 and 4 × 1/1 GN = 2× and 4×.'],p:[{t:['Kakku (1/1 GN)','Cake (1/1 GN)'],i:[[750,'g','Porkkanasose','Carrot purée'],[645,'g','Gluteeniton jauho','Gluten-free flour'],[6,'g','Ksantaani','Xanthan gum'],[22,'g','Ruokasooda','Baking soda'],[22,'g','Leivinjauhe','Baking powder'],[10,'g','Suola','Salt'],[15,'g','Kaneli','Cinnamon'],[650,'g','Fariinisokeri','Brown sugar'],[1.8,'dl','Kauramaito','Oat milk'],[1.5,'tl','Vanilja-aromi','Vanilla extract'],[3.6,'dl','Rypsiöljy','Rapeseed oil']],s:[['Sulata porkkanasose pakissa.','Thaw the carrot purée in a box.'],['Sekoita kuivat aineet keskenään.','Mix the dry ingredients.'],['Sekoita nesteet yhteen porkkanasoseen kanssa.','Mix the liquids with the carrot purée.'],['Sekoita lopuksi kuivat ja nestemäiset aineet keskenään.','Finally mix the dry and wet together.'],['Paista 175 °C n. 25 min. Muista tarkistaa kypsyys tikuttamalla!','Bake at 175 °C for about 25 min. Remember to test with a skewer!']]},{t:['Vegaani kuorrute (1/1 GN)','Vegan frosting (1/1 GN)'],i:[[150,'g','Margariini','Margarine'],[200,'g','Tomusokeri','Icing sugar'],[8,'g','Vaniljasokeri','Vanilla sugar'],[300,'g','Kaurafraiche','Oat crème fraîche']],s:[['Vaahdota margariini ja sokerit vaaleaksi vaahdoksi.','Beat the margarine and sugars until pale and fluffy.'],['Lisää kaurafraiche ja vaahdota vielä hetki.','Add the oat crème fraîche and beat a little more.'],['Jos kuorrute vaikuttaa löysältä, laita se hetkeksi kylmään.','If the frosting seems loose, chill it for a while.']]}]},
{id:'gluteeniton-vuokaleipa',c:'taikina',n:['Gluteeniton vuokaleipä','Gluten-free tin loaf'],v:1,f:'2244',note:['1× = 1 leipä. 3 leipää = 3× (suola 2 rkl).','1× = 1 loaf. 3 loaves = 3× (salt 2 tbsp).'],p:[{i:[[6,'dl','Vesi','Water'],[1,'rkl','Psyllium','Psyllium'],[2,'rkl','Pellavansiemenet','Flaxseeds'],[3,'rkl','Sekoitus eri siemeniä','Mixed seeds'],[2,'tl','Suola','Salt'],[2,'dl','Gluteenittomat kaurahiutaleet','Gluten-free oat flakes'],[11,'g','Kuivahiiva','Dry yeast'],[3.5,'dl','Tumma gluteeniton jauho','Dark gluten-free flour'],[3,'dl','Vaalea gluteeniton jauho','Light gluten-free flour']],s:[['Sekoita veteen psyllium ja siemenet, anna olla 10 min.','Mix the psyllium and seeds into the water and leave 10 min.'],['Sekoita joukkoon suola ja kaurahiutaleet, sitten kuivat aineet.','Mix in the salt and oat flakes, then the dry ingredients.'],['Jaa taikina voideltuihin vuokiin (pienemmät saaristolaisvuoat).','Divide into greased tins (the smaller archipelago-bread tins).'],['Paista 175 °C reilu tunti. Testaa kypsyys.','Bake at 175 °C for a good hour. Test for doneness.'],['Leikkaa jäähtynyt leipä siivuiksi ja pakasta n. 10 siivua per pussi.','Slice the cooled bread and freeze about 10 slices per bag.']]}]},
{id:'vegebriossi-sampyla',c:'taikina',n:['Vegebriossisämpylä','Vegan brioche bun'],v:1,f:'2245',note:['1× = 1 l kauramaitoa, n. 37 sämpylää (pala 112–114 g). 3 l = 3× (jauhoja käsin 7080 g, tarkista).','1× = 1 l oat milk, about 37 buns (112–114 g each). 3 l = 3× (flour by hand 7080 g, check).'],p:[{i:[[1,'l','Kauramaito','Oat milk'],[33,'g','Kuivahiiva','Dry yeast'],[90,'g','Sokeri','Sugar'],[20,'g','Suola','Salt'],[24,'g','No Egg','No Egg (egg replacer)'],[240,'ml','Vesi','Water'],[400,'g','Margariini','Margarine'],[2420,'g','Vehnäjauho','Wheat flour']],s:[['Ota margariini huoneenlämpöön. Lämmitä maito.','Bring the margarine to room temperature. Warm the milk.'],['Mittaa No Egg ja vesi yhteen ja vaahdota hetki.','Measure the No Egg and water together and whisk a moment.'],['Mittaa sokeri, suola, kuivahiiva ja pieni osa jauhoista yhteen.','Measure the sugar, salt, dry yeast and a little of the flour together.'],['Lisää maitoon kuiva-aineseos ja suurin osa lopuista jauhoista sekä No Egg -seos.','Add the dry mix, most of the remaining flour and the No Egg mix to the milk.'],['Vaivaa 20 min nopeudella 1.','Knead 20 min on speed 1.'],['Lisää loput jauhot sekä margariini.','Add the rest of the flour and the margarine.'],['Vaivaa vielä 5 min nopeudella 1 ja 5 min nopeudella 2.','Knead 5 more min on speed 1 and 5 min on speed 2.'],['Palapaino 112–114 g. Paina sämpylöitä hieman ennen nostatusta, nostatus höyryssä.','Piece weight 112–114 g. Press the buns a little before proving; prove in steam.'],['Paista 180 °C n. 12–15 min, käännä paiston puolivälissä.','Bake at 180 °C for about 12–15 min, turn halfway.']]}]},
{id:'pekaanipahkinapiirakka',c:'kakku',n:['Pekaanipähkinäpiirakka','Pecan pie'],f:'2246',note:['1× = 4 kpl 26 cm piirakkaa. Paistolämpö on muutettu käsin 160 °C:een ja aika 40–60 min.','1× = 4 pies of 26 cm. Baking temperature changed by hand to 160 °C and time 40–60 min.'],p:[{i:[[1040,'g','Fariinisokeri','Brown sugar'],[900,'g','Siirappi (vaalea tai vaahtera)','Syrup (light or maple)'],[200,'g','Voi','Butter'],[12,'kpl','Kananmuna','Egg'],[2.4,'dl','Kerma','Cream'],[1,'tl','Suola','Salt'],[600,'g','Pekaanipähkinä','Pecans'],[4,'kpl','Muropohja (26 cm)','Shortcrust base (26 cm)']],s:[['Kuumenna sokeri, siirappi ja voi kattilassa.','Heat the sugar, syrup and butter in a pot.'],['Vatkaa munien rakenne rikki ja lisää jäähtyneeseen siirappiseokseen.','Beat the eggs lightly and add them to the cooled syrup mix.'],['Lisää kerma ja suola.','Add the cream and salt.'],['Jaa täyte muropohjiin ja lisää päälle öljytyt pekaanipähkinät.','Divide the filling into the pie bases and top with oiled pecans.'],['Paista 160 °C 40–60 min.','Bake at 160 °C for 40–60 min.']]}]},
{id:'pavlova',c:'jalki',n:['Pavlova','Pavlova'],f:'2247',p:[{t:['Pavlova','Pavlova'],i:[[6,'kpl','Valkuainen','Egg white'],[3.75,'dl','Sokeri','Sugar'],[1,'rkl','Maizena','Cornflour'],[1.5,'tl','Omenaviinietikka','Apple cider vinegar']],s:[['Vaahdota valkuaiset höttöiseksi vaahdoksi. Jatka vaahdottamista ja lisää sokeri pikkuhiljaa. Lisää maizena.','Whisk the egg whites to a soft foam. Keep whisking and add the sugar little by little. Add the cornflour.'],['Jatka vaahdottamista, kunnes vaahto on kiiltävää ja jämäkkää. Lisää omenaviinietikka ja vatkaa vielä hetki.','Keep whisking until glossy and firm. Add the vinegar and whisk a little more.'],['Pursota massa haluttuun muotoon ja paista 110 °C n. 75 min.','Pipe into the shape you want and bake at 110 °C for about 75 min.'],['Sammuta uuni, mutta älä avaa uunin ovea! Jätä pavlovat uuniin kuivumaan seuraavaan päivään.','Turn off the oven but do not open the door! Leave the pavlovas to dry in the oven until the next day.']]},{t:['Esimerkkitäyte','Example filling'],i:[[150,'g','Tuorejuusto','Cream cheese'],[70,'g','Tomusokeri','Icing sugar'],[1.5,'dl','Kerma','Cream'],[null,'','Vaniljakreemijauhe (tarvittaessa)','Vanilla custard powder (if needed)'],[null,'','Limen mehu','Lime juice'],[null,'','Sokeri ja vaniljasokeri','Sugar and vanilla sugar'],[null,'','Mansikat','Strawberries']],s:[['Sekoita limen mehuun sokeria (ei tomusokeria) maun mukaan ja pilko mansikat joukkoon marinoitumaan. Muista maistaa!','Mix sugar (not icing sugar) into the lime juice to taste and cut the strawberries into it to marinate. Remember to taste!'],['Vaahdota hetki tuorejuustoa ja tomusokeria, lisää kerma ja vaahdota paksuksi. Jos vaahto ei paksuunnu, lisää hiukan vaniljakreemijauhetta.','Whisk the cream cheese and icing sugar a moment, add the cream and whisk thick. If it will not thicken, add a little vanilla custard powder.'],['Pursota vaahtoa pavlovien päälle ja ripottele päälle marinoidut mansikat.','Pipe the cream on the pavlovas and top with the marinated strawberries.']]}]},
{id:'valkosuklaa-inkivaari-torttu',c:'kakku',n:['Paahdettu valkosuklaa ja inkivääri-mantelikaramellitorttu','Toasted white chocolate and ginger-almond caramel tart'],f:'2248',note:['Pohjaksi kypsäksi paistettu muropohja. Paahdettu valkosuklaa: 100 °C 45–60 min. Kerrokset: muropohja → inkiväärikaramelli → valkosuklaamousse → valkosuklaaganache.','Use a fully baked shortcrust base. Toasted white chocolate: 100 °C for 45–60 min. Layers: base → ginger caramel → white chocolate mousse → white chocolate ganache.'],p:[{t:['Valkosuklaamousse','White chocolate mousse'],i:[[170,'ml','Maito','Milk'],[55,'g','Sokeri','Sugar'],[3,'kpl','Keltuainen','Egg yolk'],[2.5,'kpl','Liivatelehti','Gelatine sheet'],[150,'g','Paahdettu valkosuklaa','Toasted white chocolate'],[170,'ml','Kuohukerma','Whipping cream']],s:[['Ota suklaa huoneenlämpöön hyvissä ajoin. Vaahdota keltuaiset ja sokeri.','Bring the chocolate to room temperature in good time. Whisk the yolks and sugar.'],['Kiehauta maito ja kaada keltuaisvaahtoon koko ajan vatkaten. Laita liivatteet likoamaan.','Boil the milk and pour it into the yolks while whisking. Soak the gelatine.'],['Kaada seos takaisin kattilaan ja keitä, kunnes paksunee (75–80 °C).','Pour back into the pot and cook until it thickens (75–80 °C).'],['Sekoita kuumaan massaan suklaa ja liivatteet, kunnes kaikki on sulanut. Siivilöi.','Stir the chocolate and gelatine into the hot mix until melted. Strain.'],['Anna jäähtyä huoneenlämpöiseksi ja sekoita sitten vaahdotettu kerma joukkoon.','Cool to room temperature, then fold in the whipped cream.']]},{t:['Inkivääri-mantelikaramelli','Ginger-almond caramel'],i:[[120,'g','Kuohukerma','Whipping cream'],[0.25,'tl','Inkivääri (jauhettu)','Ground ginger'],[150,'g','Sokeri','Sugar'],[10,'g','Voi','Butter'],[150,'g','Manteli, paahdettu ja rouhittu','Almonds, toasted and chopped']],s:[['Sekoita kermaan inkiväärijauhe.','Mix the ground ginger into the cream.'],['Sulata sokeri pannulla, kunnes se on sulanut ja saanut kauniin värin.','Melt the sugar in a pan until melted and nicely coloured.'],['Kaada joukkoon puolet kermasta ja sekoita. VARO: sokeri räiskyy raivolla, kun lisäät kerman!','Pour in half of the cream and stir. CAREFUL: the sugar spits hard when you add the cream!'],['Kun seos ei enää kupli, lisää loput kermasta. Lämmitä vielä hetki, jos seassa on sokeripaakkuja.','When it stops bubbling, add the rest of the cream. Warm a little longer if there are sugar lumps.'],['Lisää voi ja mantelit. Jäähdytä hetki ja kaada muropohjan päälle.','Add the butter and almonds. Cool a moment and pour onto the base.']]},{t:['Valkosuklaaganache','White chocolate ganache'],i:[[225,'g','Paahdettu valkosuklaa','Toasted white chocolate'],[120,'g','Kuohukerma','Whipping cream']],s:[['Kuumenna kerma ja kaada suklaan päälle. Sekoita tasaiseksi.','Heat the cream and pour over the chocolate. Stir smooth.'],['Levitä mousse-kerroksen päälle.','Spread on top of the mousse layer.']],gen:1}]},
{id:'gluteeniton-tuille',c:'koriste',n:['Gluteeniton tuille','Gluten-free tuile'],f:'2249',p:[{i:[[260,'g','Gluteeniton jauhoseos (1:1:1 riisijauho, perunajauho, maizena)','Gluten-free flour mix (1:1:1 rice flour, potato starch, cornflour)'],[240,'g','Tomusokeri','Icing sugar'],[8,'kpl','Valkuainen','Egg white'],[200,'g','Ruskistettu voi','Brown butter']],s:[['Ruskista voi, anna jäähtyä.','Brown the butter and let it cool.'],['Sekoita kuivat yhteen.','Mix the dry ingredients.'],['Vatkaa valkuaisten rakenne rikki ja sekoita kuivien kanssa yhteen.','Beat the egg whites lightly and mix with the dry ingredients.'],['Lisää lopuksi voi.','Finally add the butter.'],['Pursota silikonialustalle sopivin välein ja levitä paletilla epämääräisiksi kekseiksi.','Pipe onto a silicone mat with space between and spread with a palette knife into free shapes.'],['Paista 190 °C 4–5 min.','Bake at 190 °C for 4–5 min.']]}]},
{id:'saaristolaisleipa',c:'taikina',n:['Saaristolaisleipä','Archipelago bread'],v:1,f:'2250',note:['1× = 1 l appelsiinimehua. Vuoka n. 800 g. Käsin 5 l, 6 l ja 8 l määrät, joissa hiivaa vähemmän (n. 30 g / l). Tarkista hiiva.','1× = 1 l orange juice. One tin about 800 g. Hand-written 5 l, 6 l and 8 l amounts use less yeast (about 30 g per l). Check the yeast.'],p:[{i:[[1,'l','Appelsiinimehu','Orange juice'],[100,'g','Tuorehiiva','Fresh yeast'],[300,'g','Kaljamallas','Malt flour (kalja malt)'],[60,'g','Vehnälese','Wheat bran'],[30,'g','Suola','Salt'],[725,'g','Vehnäjauho','Wheat flour'],[225,'g','Ruisjauho','Rye flour'],[300,'g','Siirappi','Syrup']],s:[['Lämmitä mehu ja lisää siirappi joukkoon.','Warm the juice and add the syrup.'],['Lisää hiiva, mallas, leseet ja suola.','Add the yeast, malt, bran and salt.'],['Lisää jauhot ja sekoita hyvin lapavatkaimella.','Add the flours and mix well with the paddle.'],['Annostele hyvin voideltuihin leipävuokiin (noin puoleenväliin, sillä kohoaa reilusti).','Portion into well-greased bread tins (about halfway, it rises a lot).'],['Nostata hyvin vuoan reunoille asti.','Prove well, up to the tin edges.'],['Paista 160 °C 60 min ja sen jälkeen 175 °C 15 min.','Bake at 160 °C for 60 min, then 175 °C for 15 min.']]}]},
{id:'banaanikakku',c:'kakku',n:['Banaanikakku','Banana cake'],f:'2251',note:['1× = 1 leipävuoka. 1/1 GN = 2,5× ja 6 × 1/1 GN = 15×.','1× = 1 loaf tin. 1/1 GN = 2.5× and 6 × 1/1 GN = 15×.'],p:[{i:[[100,'g','Piimä','Buttermilk'],[100,'g','Rypsiöljy','Rapeseed oil'],[2,'kpl','Kananmuna','Egg'],[300,'g','Banaanisose','Banana purée'],[250,'g','Muskovadosokeri','Muscovado sugar'],[250,'g','Vehnäjauho','Wheat flour'],[5,'g','Ruokasooda','Baking soda'],[15,'g','Kardemumma','Cardamom'],[15,'g','Kaneli','Cinnamon']],s:[['Sekoita piimä, öljy, kananmunat, banaanisose sekä sokeri keskenään.','Mix the buttermilk, oil, eggs, banana purée and sugar.'],['Sekoita kuivat aineet keskenään ja lisää taikinaan.','Mix the dry ingredients and add to the batter.'],['Sekoita taikina tasaiseksi ja jaa vuokiin tai pakkeihin.','Mix smooth and divide into tins or trays.'],['Paista 150 °C n. 60 min.','Bake at 150 °C for about 60 min.']]}]},
{id:'kinder-bueno-kakku',c:'kakku',n:['Kinder Bueno -kakku','Kinder Bueno cake'],f:'2252',note:['1× = 1 kakku. Paperissa myös 3× (käsin) ja 4 kpl määrät.','1× = 1 cake. Paper also has 3× (by hand) and 4-cake amounts.'],p:[{t:['Pohja','Base'],i:[[300,'g','Dominokeksit','Domino biscuits'],[100,'g','Voi','Butter']],s:[['Murskaa keksit ja sulata voi, sekoita keskenään.','Crush the biscuits, melt the butter and mix together.'],['Painele vuoan pohjalle ja reunoille.','Press onto the bottom and sides of the tin.']]},{t:['Täyte','Filling'],i:[[500,'g','Tuorejuusto','Cream cheese'],[100,'g','Tomusokeri','Icing sugar'],[300,'g','Kuohukerma','Whipping cream'],[250,'g','Kinder Maxi -patukat','Kinder Maxi bars'],[1,'tl','Vanilja-aromi','Vanilla extract'],[12,'kpl','Kinder Bueno -patukat','Kinder Bueno bars']],s:[['Paloittele puolet buenoista vuoan pohjalle ja leikkaa loput hienoksi moussea varten.','Cut half of the Buenos onto the base and chop the rest finely for the mousse.'],['Sulata ¼ kermasta maxipatukoiden kanssa.','Melt ¼ of the cream with the Maxi bars.'],['Vatkaa tuorejuusto, tomusokeri ja vanilja keskenään, lisää sulatetut maxit.','Beat the cream cheese, icing sugar and vanilla, add the melted Maxis.'],['Lisää kerma ja vaahdota, kunnes paksua. Sekoita lopuksi joukkoon buenomuru.','Add the cream and whisk until thick. Finally mix in the Bueno crumbs.'],['Lusikoi massa vuokaan buenopalojen päälle.','Spoon the mix into the tin over the Bueno pieces.']]}]},
{id:'mantelicrisp',c:'koriste',n:['Mantelicrisp','Almond crisp'],v:1,f:'2253',note:['1× = 5 peltiä.','1× = 5 trays.'],p:[{i:[[200,'g','Eleplant kasvirasva','Eleplant plant fat'],[220,'g','Ruokokidesokeri','Cane sugar'],[130,'g','Mantelijauhe','Almond flour'],[80,'g','Mantelilastu','Flaked almonds'],[2,'g','Suola','Salt'],[2,'tl','Vaniljasokeri','Vanilla sugar'],[60,'ml','Kauramaito','Oat milk']],s:[['Sulata rasva ja sekoita kaikki loput aineet rasvan joukkoon.','Melt the fat and mix everything else into it.'],['Jaa pelleille ja levitä paletilla ohueksi. Ei haittaa, jos pinnassa on reikiä tai hieman epätasaisuutta. HUOM! Taikina leviää uunissa!','Divide onto trays and spread thin with a palette knife. Holes or a slightly uneven surface are fine. NOTE: the batter spreads in the oven!'],['Paista 160 °C puolipuhalluksella 7–9 min.','Bake at 160 °C on half fan for 7–9 min.']]}]},
{id:'piparimutakakku',c:'kakku',n:['Piparimutakakku (gluteeniton)','Gingerbread mud cake (gluten-free)'],f:'2254',note:['1× = 1 kakku. 6 kakkua = 6× (leivinjauhe 2 rkl, suola 2,5 tl).','1× = 1 cake. 6 cakes = 6× (baking powder 2 tbsp, salt 2.5 tsp).'],p:[{i:[[200,'g','Voi','Butter'],[200,'g','Tumma suklaa','Dark chocolate'],[4,'kpl','Kananmuna','Egg'],[2,'dl','Muscovado- tai fariinisokeri','Muscovado or brown sugar'],[2.5,'dl','Gluteenittomat jauhot','Gluten-free flour'],[1,'tl','Leivinjauhe','Baking powder'],[1,'rkl','Piparkakkumauste','Gingerbread spice'],[0.25,'tl','Suola','Salt']],s:[['Sulata voi ja suklaa. Anna jäähtyä.','Melt the butter and chocolate. Let cool.'],['Vaahdota munat ja sokeri kovaksi vaahdoksi.','Whisk the eggs and sugar to a firm foam.'],['Sekoita kuivat aineet yhteen.','Mix the dry ingredients.'],['Lisää suklaaseos munavaahtoon ja sihtaa kuivat joukkoon.','Add the chocolate to the egg foam and sift in the dry ingredients.'],['Paista 175 °C 15–18 min, kunnes pinta on paahtunut ja reunat hieman irronneet.','Bake at 175 °C for 15–18 min until the top is toasted and the edges have come away a little.']]}]},
{id:'joululimppu',c:'taikina',n:['Joululimppu','Christmas rye loaf'],f:'2255',note:['1× = 2 limppua.','1× = 2 loaves.'],p:[{t:['Taikina','Dough'],i:[[50,'g','Hiiva (1 pkt)','Yeast (1 pack)'],[5,'dl','Piimä (½ prk)','Buttermilk (½ carton)'],[1,'dl','Siirappi','Syrup'],[1.5,'tl','Suola','Salt'],[1,'tl','Pomeranssinkuori','Bitter orange peel'],[1,'tl','Fenkolinsiemenet','Fennel seeds'],[1,'tl','Kumina','Caraway'],[3,'rkl','Rypsiöljy','Rapeseed oil'],[8.5,'dl','Vehnäjauhot (8–9 dl)','Wheat flour (8–9 dl)'],[3,'dl','Ruisjauhot','Rye flour']],s:[['Liuota hiiva kädenlämpöiseen piimään. Lisää siirappi, mausteet ja öljy.','Dissolve the yeast in lukewarm buttermilk. Add the syrup, spices and oil.'],['Alusta jauhot taikinaan. Kohota huoneenlämmössä liinalla peitettynä noin 1 tunti.','Knead in the flours. Let rise at room temperature under a cloth for about 1 hour.'],['Säädä uuni 175 °C:een. Vaivaa kohonneesta taikinasta ilmakuplat jauhotetulla alustalla ja jaa kahteen osaan.','Set the oven to 175 °C. Knead the air out of the risen dough on a floured surface and divide in two.'],['Muotoile kaksi pyöreää limppua, laita leivinpaperille pellille ja kohota liinalla peitettynä vähintään 30 min, jotta limput eivät repeile.','Shape two round loaves, put on a lined tray and let rise under a cloth for at least 30 min so they do not crack.'],['Kypsennä uunissa 25 min.','Bake for 25 min.']]},{t:['Voitelu','Glaze'],i:[[0.5,'dl','Vesi','Water'],[0.5,'dl','Siirappi','Syrup']],s:[['Sekoita vesi ja siirappi.','Mix the water and syrup.'],['Ota limput uunista ja sivele pinta siirappivedellä.','Take the loaves out and brush with the syrup water.'],['Laita takaisin uuniin 45–50 min ja sivele noin 10 min välein.','Put back in the oven for 45–50 min and brush about every 10 min.'],['Anna limppujen jäähtyä peittämättä.','Let the loaves cool uncovered.']]}]},
{id:'mirror-glaze',c:'koriste',n:['Mirror glaze (peilikiille)','Mirror glaze'],f:'2256',note:['Tällä määrällä kuorruttaa ainakin 2 kakkua.','This covers at least 2 cakes.'],p:[{i:[[3,'kpl','Liivatelehti (tai 1,5 isoa)','Gelatine sheet (or 1.5 large)'],[220,'g','Kuohukerma','Whipping cream'],[10,'g','Glukoosisiirappi','Glucose syrup'],[225,'g','Valkosuklaa','White chocolate'],[25,'g','Rypsiöljy','Rapeseed oil'],[null,'','Pastaväri','Paste colour']],s:[['Rouhi valkosuklaa pienemmäksi. Laita liivatteet likoamaan kylmään veteen.','Chop the white chocolate. Soak the gelatine in cold water.'],['Kiehauta kerma ja glukoosisiirappi. Kaada valkosuklaan joukkoon ja sekoita tasaiseksi.','Boil the cream and glucose. Pour over the white chocolate and stir smooth.'],['Lisää liivatteet ja sekoita tasaiseksi.','Add the gelatine and stir smooth.'],['Lisää öljy ja pastaväri.','Add the oil and paste colour.'],['Soseuta sauvasekoittimella ja kaada siivilän läpi.','Blend with a stick blender and pour through a sieve.'],['Anna jäähtyä hetki ja käytä viimeistään 32 °C:ssa. Kaada jäisen kakun pintaan. Kerää ylijäämä talteen.','Let cool a little and use at 32 °C at the latest. Pour over a frozen cake. Save the excess.']]}]},
{id:'kinderkakku',c:'kakku',n:['Kinderkakku','Kinder cake'],f:'2257',note:['1× = 1 kakku. 4 kakkua = 4×.','1× = 1 cake. 4 cakes = 4×.'],p:[{i:[[300,'g','Dominokeksit','Domino biscuits'],[100,'g','Voi','Butter'],[500,'g','Tuorejuusto','Cream cheese'],[100,'g','Tomusokeri','Icing sugar'],[300,'g','Kuohukerma','Whipping cream'],[250,'g','Kinder Maxi','Kinder Maxi'],[1,'tl','Vanilja-aromi','Vanilla extract'],[2,'kpl','Kinder Bueno -patukka','Kinder Bueno bar']],s:[['Murskaa dominot ja sekoita joukkoon sula voi. Painele vuokien pohjille.','Crush the Dominos and mix in the melted butter. Press into the tin bottoms.'],['Sulata Kinder Maxi. Vatkaa tuorejuusto, sokeri ja vanilja-aromi sekaisin.','Melt the Kinder Maxi. Beat the cream cheese, sugar and vanilla.'],['Vaahdota kerma kovaksi vaahdoksi.','Whip the cream to stiff peaks.'],['Sekoita suklaa tuorejuustoon ja lisää lopuksi kermavaahto.','Mix the chocolate into the cream cheese and finally add the whipped cream.'],['Kaada puolet moussesta pohjan päälle, laita Kinder Bueno -palat väliin ja kaada loppu mousse päälle.','Pour half of the mousse on the base, add the Bueno pieces and pour the rest on top.']]}]},
{id:'suklaakreemi',c:'kreemi',n:['Suklaakreemi','Chocolate frosting'],f:'2258',note:['Tällä määrällä kuorrutat n. 10 muffinssia.','This frosts about 10 muffins.'],p:[{i:[[100,'g','Voi, huoneenlämpöinen','Butter, room temperature'],[350,'g','Mascarpone, huoneenlämpöinen','Mascarpone, room temperature'],[500,'g','Suklaa','Chocolate']],s:[['Sulata suklaa. Sekoita voi ja mascarpone yhteen.','Melt the chocolate. Mix the butter and mascarpone.'],['Lisää suklaa ja vaahdota, kunnes tasaista ja kuohkeaa.','Add the chocolate and whisk until smooth and fluffy.']]}]},
{id:'toscatayte',c:'koriste',n:['Toscatäyte (26 cm piirakka)','Tosca topping (26 cm pie)'],f:'2259',note:['1× = 1 kpl 26 cm piirakka.','1× = one 26 cm pie.'],p:[{i:[[150,'g','Mantelilastut','Flaked almonds'],[100,'g','Voi','Butter'],[85,'g','Sokeri','Sugar'],[100,'g','Kuohukerma','Whipping cream'],[1,'rkl','Vehnäjauho tai maizena','Wheat flour or cornflour']],s:[['Sulata voi kattilassa. Lisää kerma, sokeri ja lastut. Kuumenna, kunnes sokeri hieman sulaa.','Melt the butter in a pot. Add the cream, sugar and almonds. Heat until the sugar melts a little.'],['Lisää jauhot pikkuhiljaa. Keittele n. 10 min.','Add the flour little by little. Simmer about 10 min.'],['Kaada pohjan päälle ja paista 175 °C n. 10 min tai kunnes kullanruskea.','Pour onto the base and bake at 175 °C for about 10 min or until golden.']]}]},
{id:'appelsiini-suklaakakku',c:'kakku',n:['Appelsiini-suklaakakku','Orange chocolate cake'],f:'2260',note:['1× = 1 kakku. 6 kakkua = 6×. Kuorruta halutessasi tummalla suklaaganachella 50/50.','1× = 1 cake. 6 cakes = 6×. Optionally cover with 50/50 dark chocolate ganache.'],p:[{i:[[200,'g','Digestive-keksit','Digestive biscuits'],[100,'g','Voi','Butter'],[350,'g','Tumma suklaa','Dark chocolate'],[225,'g','Sokeri','Sugar'],[400,'g','Mascarpone','Mascarpone'],[1,'kpl','Appelsiinin kuori','Orange zest'],[400,'g','Kuohukerma','Whipping cream']],s:[['Murskaa keksit ja sekoita joukkoon sulatettu voi. Painele vuokien pohjille.','Crush the biscuits and mix in the melted butter. Press into the tin bottoms.'],['Sulata suklaa.','Melt the chocolate.'],['Vatkaa sokeri ja mascarpone pehmeäksi. Lisää raastettu appelsiininkuori ja suklaa.','Beat the sugar and mascarpone soft. Add the grated orange zest and chocolate.'],['Vaahdota kerma pehmeäksi vaahdoksi ja sekoita suklaavaahdon joukkoon.','Whip the cream to soft peaks and fold into the chocolate mix.'],['Jaa vaahto keksipohjien päälle.','Spread the mousse on the biscuit bases.']]}]},
{id:'juuripatonki',c:'taikina',n:['Juuripatonki','Sourdough baguette'],v:1,f:'2261',note:['Palapaino 440–460 g. Paperissa myös ×3, ×4 ja ×5 määrät.','Piece weight 440–460 g. Paper also has ×3, ×4 and ×5 amounts.'],p:[{i:[[414,'g','Vehnäjuuri','Wheat sourdough starter'],[780,'g','Vehnäjauho','Wheat flour'],[600,'g','Vesi','Water'],[25,'ml','Suola','Salt']],s:[['Sekoita juuri, jauhot ja vesi sekaisin, anna levätä 30 min.','Mix the starter, flour and water and rest 30 min.'],['Vaivaa nopeudella 1 10 min, lisää jauhoja, kunnes taikina irtoaa hieman kulhon pohjasta.','Knead on speed 1 for 10 min, adding flour until it comes away a little from the bowl.'],['Lisää suola ja vaivaa vielä 10 min nopeudella 2.','Add the salt and knead 10 more min on speed 2.'],['Nosta taikina öljyttyyn astiaan ja anna levätä 1,5 tuntia.','Put the dough in an oiled container and rest 1.5 hours.'],['Taittele taikina 3 kertaa. Nosta peitettynä kylmään ja leivo seuraavana päivänä.','Fold the dough 3 times. Put it covered in the cold and shape the next day.'],['Esilämmitä uuni 250 °C, laita patongit uuniin ja laske lämpö 200 °C:een. Paina höyryä 2 kertaa. Paista 22–24 min.','Preheat the oven to 250 °C, put the baguettes in and lower to 200 °C. Steam twice. Bake 22–24 min.']]}]},
{id:'blankon-jauhoton-suklaakakku',c:'kakku',n:['Blankon jauhoton suklaakakku','Blanko flourless chocolate cake'],f:'2262',note:['1× = 1 kakku. 10 kakkua = 10×.','1× = 1 cake. 10 cakes = 10×.'],p:[{t:['Kakku','Cake'],i:[[245,'g','Tumma suklaa','Dark chocolate'],[168,'g','Voi','Butter'],[215,'g','Sokeri','Sugar'],[0.5,'tl','Suola','Salt'],[1.5,'tl','Espressojauhe','Espresso powder'],[1.5,'tl','Vanilja-aromi','Vanilla extract'],[4,'kpl','Kananmuna','Egg'],[62,'g','Kaakaojauhe','Cocoa powder']],s:[['Sulata voi ja suklaa kattilassa.','Melt the butter and chocolate in a pot.'],['Sekoita joukkoon sokeri, suola, espressojauhe ja vanilja-aromi.','Stir in the sugar, salt, espresso powder and vanilla.'],['Lisää munat.','Add the eggs.'],['Lisää kaakao ja sekoita vain sekaisin.','Add the cocoa and mix only until combined.'],['Jaa massa paperoituihin ja rasvattuihin vuokiin. Paista 165 °C (kiertoilma) 25 min.','Divide into lined, greased tins. Bake at 165 °C (fan) for 25 min.']]},{t:['Kuorrute','Topping'],i:[[245,'g','Tumma suklaa','Dark chocolate'],[162,'g','Kuohukerma','Whipping cream']],s:[['Sulata yhdessä ja anna jämähtää jonkin verran ennen kakun päälle laittoa.','Melt together and let it firm up a little before topping the cake.'],['Levitä lusikalla kakun päälle, jotta saat "villin" pinnan.','Spread on the cake with a spoon for a "wild" surface.']]}]},
{id:'sitruunatayte',c:'kastike',n:['Sitruunatäyte (26 cm piirakka)','Lemon filling (26 cm pie)'],f:'2263',note:['1× = 1 kpl 26 cm piirakka. 4 kpl = 4×. Käsin myös 3× määrät.','1× = one 26 cm pie. 4 pies = 4×. Also 3× amounts by hand.'],p:[{i:[[1,'kpl','Sitruunan kuori','Lemon zest'],[1,'dl','Sokeri','Sugar'],[2,'dl','Vesi, kylmä','Water, cold'],[36,'g','Maizena','Cornflour'],[0.5,'dl','Sitruunamehu','Lemon juice'],[2,'kpl','Keltuainen','Egg yolk'],[50,'g','Voi, huoneenlämpöinen','Butter, room temperature']],s:[['Laita sokeri ja sitruunankuoriraaste kattilaan.','Put the sugar and grated lemon zest in a pot.'],['Sekoita kylmä vesi ja maizena ja lisää kattilaan.','Mix the cold water and cornflour and add to the pot.'],['Kuumenna koko ajan sekoittaen, kunnes kiehahtaa.','Heat while stirring all the time until it boils.'],['Lisää sitruunamehu ja keltuaiset ja ota kattila pois liedeltä.','Add the lemon juice and yolks and take the pot off the heat.'],['Vatkaa joukkoon huoneenlämpöinen voi.','Whisk in the room-temperature butter.'],['Kaada täyte esipaistetun muropohjan päälle ja hyydytä hetki 175 °C uunissa.','Pour onto the pre-baked shortcrust base and set briefly in a 175 °C oven.']]}]},
{id:'hampurilaissampylat',c:'taikina',n:['Hampurilaissämpylät','Burger buns'],f:'2264',note:['1× = 3 l maitoa. Käytä isoa pataa! Teipissä käsin 2 l erä (n. 80 kpl). Voitele reilulla keltuaismunalla.','1× = 3 l milk. Use the big bowl! The tape has a 2 l batch by hand (about 80 pcs). Brush generously with egg yolk.'],p:[{i:[[3,'l','Laktoositon maito','Lactose-free milk'],[300,'g','Tuorehiiva','Fresh yeast'],[270,'g','Sokeri','Sugar'],[60,'g','Suola','Salt'],[24,'kpl','Kananmuna','Egg'],[1200,'g','Pehmeä voi','Soft butter'],[7260,'g','Vehnäjauho','Wheat flour'],[null,'','Keltuainen voiteluun','Egg yolk for brushing']],s:[['Lämmitä maito.','Warm the milk.'],['Sekoita joukkoon hiiva, sokeri, suola, kananmunat ja osa jauhoista.','Mix in the yeast, sugar, salt, eggs and some of the flour.'],['Vaivaa taikinaa nopeudella 1 20 min.','Knead on speed 1 for 20 min.'],['Lisää pehmeä voi sekä loput jauhot ja vaivaa nopeudella 1 vielä 10 min.','Add the soft butter and the rest of the flour and knead 10 more min on speed 1.'],['Palapaino 108–112 g.','Piece weight 108–112 g.'],['Kohota hyvin ja voitele reilulla keltuaismunalla.','Prove well and brush generously with egg yolk.'],['Paista 175 °C n. 12 min.','Bake at 175 °C for about 12 min.']]}]},
{id:'cookie-dough-jaatelo',c:'jaatelo',n:['Cookie dough -jäätelö','Cookie dough ice cream'],v:1,f:'2265',note:['N. 33 annosta. Käsin ½-erä maapähkinäversiona: 5 dl Oddlygood, 1 prk kond. kookosmaito, 1,5 dl kauravanilja, 42 g glukoosisiirappi, 175 g maapähkinävoi (smooth), 100 g murskattu suolapähkinä.','About 33 portions. By hand a ½ batch peanut version: 5 dl Oddlygood, 1 can condensed coconut milk, 1.5 dl oat vanilla custard, 42 g glucose, 175 g smooth peanut butter, 100 g crushed salted peanuts.'],p:[{i:[[1,'l','Kauravispi','Oat whipping cream'],[640,'g','Kondensoitu kookosmaito (2 prk)','Condensed coconut milk (2 cans)'],[3,'dl','Kauravaniljakastike','Oat vanilla custard'],[4,'kpl','Vaniljatanko','Vanilla pod'],[84,'g','Glukoosisiirappi','Glucose syrup'],[300,'g','Cookie dough','Cookie dough']],s:[['Sekoita keskenään kondensoitu kookosmaito, vaniljakastike, vaniljatangon siemenet ja glukoosisiirappi.','Mix the condensed coconut milk, vanilla custard, vanilla seeds and glucose.'],['Vaahdota kauravispi kovaksi vaahdoksi.','Whip the oat cream to stiff peaks.'],['Kutteroi jäistä cookie-taikinaa hienommaksi.','Chop the frozen cookie dough finer in the cutter.'],['Vatkaa kauravispin joukkoon vaniljaseos ja nostele lopuksi joukkoon cookie-muru.','Whisk the vanilla mix into the oat cream and finally fold in the cookie crumbs.'],['Lasipurkkiin: jäätelömassa → cookie dough → jäätelömassa → cookie dough.','In a glass jar: ice cream → cookie dough → ice cream → cookie dough.'],['Kelmuta purkit ja pakasta.','Cover the jars with film and freeze.']]}]},
{id:'pistaasifilo',c:'koriste',n:['Pistaasifilo','Pistachio filo crisp'],f:'2266',p:[{i:[[5,'levy','Filotaikina','Filo pastry'],[null,'','Jauhettu pistaasi','Ground pistachios'],[null,'','Sokeriseos 50/50 fariini + ruokokidesokeri','Sugar mix 50/50 brown + cane sugar'],[null,'','Sula voi tai sula Eleplant','Melted butter or melted Eleplant']],s:[['Laita 5 kerrosta filotaikinaa. Sivele kerrosten väliin sulaa voita tai Eleplantia.','Layer 5 sheets of filo. Brush melted butter or Eleplant between the layers.'],['Ripottele kerrosten väleihin jauhettua pistaasia ja sokeriseosta.','Sprinkle ground pistachios and the sugar mix between the layers.'],['Laita lopuksi leivinpaperi päälle ja paista kahden pellin välissä 180 °C 20 min.','Finally put baking paper on top and bake between two trays at 180 °C for 20 min.']]}]},
{id:'pistaasituille',c:'koriste',n:['Pistaasituille','Pistachio tuile'],f:'2267',note:['1× = 1 valkuainen (33 g). 4 valkuaista = 4×.','1× = 1 egg white (33 g). 4 egg whites = 4×.'],p:[{i:[[33,'g','Valkuainen (1 kpl)','Egg white (1 pc)'],[50,'g','Sokeri','Sugar'],[25,'g','Vehnäjauho','Wheat flour'],[15,'g','Voi, sulatettu','Butter, melted'],[null,'','Pistaasi, veitsellä leikattu','Pistachios, knife-chopped']],s:[['Sekoita valkuainen ja sokeri hyvin sekaisin. Lisää jauhot ja lopuksi sula voi.','Mix the egg white and sugar well. Add the flour and finally the melted butter.'],['Pursota silikonimaton päälle noin 3 cm kokoisia keksejä, vedä paletilla pisaran muotoiseksi ja ripottele pistaasia päälle.','Pipe about 3 cm rounds onto a silicone mat, drag into a teardrop with a palette knife and sprinkle pistachios on top.'],['Paista 190 °C 4–5 min.','Bake at 190 °C for 4–5 min.']]}]},
{id:'juuripatonki-leipa',c:'taikina',n:['Juuripatonki ja -leipä','Sourdough baguette and loaf'],v:1,f:'2268',note:['1× = n. 5 patonkia. Paperissa myös 1,5× (käsin, = 4 leipää), 10 kpl (2×) ja 15 kpl (3×). Patongin palapaino 500 g, leivän 1300 g.','1× = about 5 baguettes. Paper also has 1.5× (by hand, = 4 loaves), 10 pcs (2×) and 15 pcs (3×). Baguette 500 g, loaf 1300 g.'],p:[{i:[[336,'g','Juuri','Sourdough starter'],[870,'g','Kylmä vesi','Cold water'],[1200,'g','Vehnäjauho','Wheat flour'],[50,'g','Kaurahiutale','Oat flakes'],[80,'g','Siemenet','Seeds'],[25,'g','Kuivahiiva','Dry yeast'],[44,'g','Sormisuola','Flake salt'],[100,'g','Tumma siirappi','Dark syrup']],s:[['Sekoita kaikki aineet laatikossa sekaisin ja laita kylmään yön yli nousemaan.','Mix everything in a box and leave in the cold overnight to rise.'],['Patongin palapaino 500 g, leivän 1300 g. Nostata hyvin.','Baguette pieces 500 g, loaves 1300 g. Prove well.'],['Lämmitä uuni 250 °C, laita patongit uuniin ja laske lämpö 200 °C:een. Paina höyryä pari kertaa.','Heat the oven to 250 °C, put the bread in and lower to 200 °C. Steam a couple of times.'],['Patonki 25 min, leipä 35 min.','Baguette 25 min, loaf 35 min.']]}]},
{id:'pizzataikina',c:'taikina',n:['Pizzataikina (durum)','Pizza dough (durum)'],v:1,f:'2269',note:['1× = 1 l vettä. Paperissa myös 3 l, 4 l ja 6 l. Kuivahiivan alkuperäinen määrä on peitetty: käsin 6 l = 100 g, eli n. 16,6 g / l (tarkista).','1× = 1 l water. Paper also has 3 l, 4 l and 6 l. The original dry yeast amount is covered: by hand 6 l = 100 g, so about 16.6 g per l (check).'],p:[{i:[[1,'l','Jääkylmä vesi','Ice-cold water'],[1500,'g','Durumjauho','Durum flour'],[8,'g','Sokeri','Sugar'],[30,'g','Suola','Salt'],[16.6,'g','Kuivahiiva','Dry yeast'],[2,'dl','Oliiviöljy','Olive oil']],s:[['Laita vesi jäihin kylmenemään.','Put the water on ice to chill.'],['Punnitse kaikki aineet isoon pataan ja vaivaa ainakin 15 min, josta 5 min nopeudella 2.','Weigh everything into the big bowl and knead at least 15 min, of which 5 min on speed 2.'],['Pizzapallo 150–155 g, pitapallo 100 g, lounaan pitarulla 120 g.','Pizza ball 150–155 g, pita ball 100 g, lunch pita roll 120 g.']]}]},
{id:'manteli-murotaikina',c:'taikina',n:['Manteli-murotaikina ja suolainen piirakkataikina','Almond shortcrust and savoury pie dough'],f:'2270',note:['Manteli-murotaikina: 1× = 4 kpl 26 cm pohjaa (1 pohja = 490 g). 8 kpl = 2×. Suolainen piirakkataikina: 1× = 1 kpl 24–26 cm, 1 GN = 2,5×.','Almond shortcrust: 1× = four 26 cm bases (1 base = 490 g). 8 = 2×. Savoury pie dough: 1× = one 24–26 cm, 1 GN = 2.5×.'],p:[{t:['Manteli-murotaikina (4 × 26 cm)','Almond shortcrust (4 × 26 cm)'],i:[[912,'g','Vehnäjauho','Wheat flour'],[100,'g','Mantelijauhe','Almond flour'],[275,'g','Tomusokeri','Icing sugar'],[600,'g','Kylmä voi','Cold butter'],[80,'g','Keltuainen','Egg yolk']],s:[['Sekoita kuivat aineet yhteen ja lisää kylmä, pienemmäksi paloiteltu voi.','Mix the dry ingredients and add the cold, cubed butter.'],['Sekoita murumaiseksi seokseksi.','Mix to a crumbly texture.'],['Lisää keltuaiset ja sekoita nopeasti sekaisin, älä turhaan vaivaa.','Add the yolks and mix quickly; do not overwork.']]},{t:['Suolainen piirakkataikina (1 × 24–26 cm)','Savoury pie dough (1 × 24–26 cm)'],i:[[100,'g','Kylmä voi','Cold butter'],[162,'g','Vehnäjauho','Wheat flour'],[0.5,'dl','Parmesaanraaste','Grated parmesan'],[30,'ml','Kylmä vesi','Cold water']],s:[['Sekoita voi ja vehnäjauhot murumaiseksi seokseksi.','Rub the butter and flour to a crumbly mix.'],['Lisää juustoraaste ja vesi. Sekoita vain nopeasti sekaisin, älä vaivaa.','Add the cheese and water. Mix quickly only; do not knead.']]}]},
{id:'gluteeniton-pizzapohja',c:'taikina',n:['Gluteeniton pizzapohja ja sämpylä','Gluten-free pizza base and bun'],v:1,f:'2271',note:['1× = 1 l vettä. 2 l = 2× ja 3 l = 3×. Käytä tummaa gluteenitonta jauhoseosta. Pizzan palapaino 180–190 g.','1× = 1 l water. 2 l = 2× and 3 l = 3×. Use the dark gluten-free flour mix. Pizza piece 180–190 g.'],p:[{i:[[1,'l','Lämmin vesi','Warm water'],[60,'g','Sokeri','Sugar'],[60,'g','Kuivahiiva','Dry yeast'],[28,'g','Suola','Salt'],[840,'g','Gluteeniton jauhoseos (tumma)','Gluten-free flour mix (dark)'],[160,'g','Mantelijauhe','Almond flour'],[40,'g','Psylliumi','Psyllium'],[20,'g','Ksantaani','Xanthan gum'],[80,'g','Oliiviöljy','Olive oil'],[200,'g','Taikinajuuri','Sourdough starter']],s:[['Sekoita hyvin padassa vesi, sokeri, kuivahiiva ja suola. Anna levätä 3 min.','Mix the water, sugar, dry yeast and salt well in the bowl. Rest 3 min.'],['Lisää loput aineet ja vaivaa 4 min.','Add the rest and knead 4 min.'],['Punnitse paloiksi, pyöritä palloiksi ja nostata liinan alla 30 min.','Weigh into pieces, roll into balls and prove under a cloth for 30 min.'],['Pizza: kaulitse ohueksi ja leikkaa soikeaksi muotin avulla. Paista 200 °C 4–5 min.','Pizza: roll thin and cut into an oval with the cutter. Bake at 200 °C for 4–5 min.']]}]},
{id:'porkkanakakku',c:'kakku',n:['Porkkanakakku (tattari)','Carrot cake (buckwheat)'],f:'2272',note:['1× = 1 kakku. Paperissa 8 kpl 24 cm vuokaa = 8×, ja käsin 6 kpl ja 4 kpl.','1× = 1 cake. Paper has 8 tins of 24 cm = 8×, and by hand 6 and 4 cakes.'],p:[{t:['Kakku','Cake'],i:[[3,'kpl','Kananmuna','Egg'],[128,'g','Sokeri','Sugar'],[105,'g','Fariinisokeri','Brown sugar'],[3.75,'dl','Porkkanaraaste','Grated carrot'],[75,'g','Mantelijauhe','Almond flour'],[169,'g','Tattarijauho','Buckwheat flour'],[1.5,'tl','Leivinjauhe','Baking powder'],[1.5,'tl','Ruokasooda','Baking soda'],[3,'tl','Kaneli','Cinnamon'],[1.5,'tl','Kardemumma','Cardamom'],[3,'tl','Vaniljasokeri','Vanilla sugar'],[1.5,'dl','Rypsiöljy','Rapeseed oil']],s:[['Raasta porkkanat. Punnaa kuivat aineet keskenään sekaisin.','Grate the carrots. Weigh the dry ingredients together.'],['Vatkaa munat ja sokeri sekaisin, lisää porkkanaraaste.','Whisk the eggs and sugar, add the grated carrot.'],['Lisää kuivat aineet ja öljy vuorotellen taikinaan.','Add the dry ingredients and oil in turns.'],['Jaa leivinpaperoituihin vuokiin ja paista 160 °C n. 50 min. Testaa kypsyys tikulla.','Divide into lined tins and bake at 160 °C for about 50 min. Test with a skewer.']]},{t:['Tuorejuustokuorrute (1 kakku)','Cream cheese frosting (1 cake)'],i:[[450,'g','Tuorejuusto','Cream cheese'],[150,'g','Tomusokeri','Icing sugar'],[8,'g','Vaniljasokeri','Vanilla sugar']],s:[['Vaahdota kaikki ainekset sekaisin, kunnes paksuuntunut.','Whisk everything together until thick.']]}]},
{id:'paistettu-valkosuklaajuustokakku',c:'kakku',n:['Paistettu valkosuklaajuustokakku','Baked white chocolate cheesecake'],f:'2273',note:['1× = 1 kakku (24 cm). 4 kakkua = 4×.','1× = 1 cake (24 cm). 4 cakes = 4×.'],p:[{t:['Pohja','Base'],i:[[200,'g','Digestive-keksit','Digestive biscuits'],[75,'g','Voi, sulatettu','Butter, melted']],s:[['Murskaa digestivet, sekoita voi joukkoon ja painele 24 cm leivinpaperoidun vuoan pohjalle.','Crush the digestives, mix in the butter and press into a lined 24 cm tin.']]},{t:['Täyte','Filling'],i:[[864,'g','Tuorejuusto','Cream cheese'],[216,'g','Ranskankerma','Crème fraîche'],[288,'g','Valkosuklaa, sulatettu','White chocolate, melted'],[21,'ml','Sitruunamehu, siivilöity','Lemon juice, strained'],[3,'kpl','Kananmuna','Egg'],[120,'g','Tomusokeri','Icing sugar']],s:[['Ota tuorejuusto ja ranskankerma hyvissä ajoin lämpenemään huoneenlämpöön.','Bring the cream cheese and crème fraîche to room temperature in good time.'],['Sekoita kaikki aineet yhteen ja kaada pohjan päälle vuokaan.','Mix everything together and pour onto the base.'],['Laita halutessasi marja- tai hedelmäkastiketta tai hilloa päälle ja marmoroi pinta.','Optionally add berry or fruit sauce or jam on top and marble the surface.'],['Paista 150 °C 40–50 min, kaikki puhallukset pois.','Bake at 150 °C for 40–50 min with the fan off.'],['Avaa uunin ovea hetkeksi ja sulje ovi.','Open the oven door for a moment and close it.'],['Sammuta uuni ja anna kakun olla jälkilämmössä 1 tunti.','Turn off the oven and leave the cake in the residual heat for 1 hour.']]},{t:['Esimerkkikastike (1 kakku)','Example sauce (1 cake)'],i:[[200,'g','Pakastemustikat','Frozen blueberries'],[45,'g','Sokeri','Sugar'],[1,'rkl','Perunajauho','Potato starch']],s:[['Keitä kaikkia aineita kattilassa, kunnes kiehahtaa ja paksuuntuu.','Cook everything in a pot until it boils and thickens.'],['Käytä jäähtyneenä juustokakkuun.','Use cooled on the cheesecake.']]}]},
{id:'omenablondiekakku',c:'kakku',n:['Omenablondiekakku (gluteeniton)','Apple blondie cake (gluten-free)'],f:'2274',note:['1× = 1 kakku. 2 kakkua = 2×.','1× = 1 cake. 2 cakes = 2×.'],p:[{t:['Blondiepohja','Blondie base'],i:[[170,'g','Voi','Butter'],[220,'g','Fariinisokeri','Brown sugar'],[1,'rkl','Vanilja-aromi','Vanilla extract'],[1,'kpl','Kananmuna','Egg'],[1,'kpl','Valkuainen','Egg white'],[200,'g','Gluteeniton jauho','Gluten-free flour'],[0.5,'tl','Kaneli','Cinnamon'],[1,'tl','Omenamausteseos','Apple spice mix'],[0.75,'tl','Leivinjauhe','Baking powder'],[0.25,'tl','Ruokasooda','Baking soda'],[0.5,'tl','Suola','Salt'],[1,'kpl','Hapan omena','Sour apple']],s:[['Sulata voi. Lisää sokeri ja sekoita. Lisää vanilja, kananmuna ja valkuainen ja sekoita hyvin.','Melt the butter. Add the sugar and mix. Add the vanilla, egg and egg white and mix well.'],['Sekoita kuivat aineet massaan. Lopuksi pilkottu omena.','Mix in the dry ingredients. Finally the chopped apple.'],['Paista leivinpaperoidussa vuoassa 160 °C n. 25–30 min.','Bake in a lined tin at 160 °C for about 25–30 min.']]},{t:['Kinuskijuustokakkutäyte','Toffee cheesecake filling'],i:[[1.5,'dl','Fariinisokeri (kinuskiin)','Brown sugar (for the toffee)'],[1.5,'dl','Kuohukerma (kinuskiin)','Whipping cream (for the toffee)'],[450,'g','Tuorejuusto','Cream cheese'],[100,'g','Sokeri','Sugar'],[0.5,'tl','Omenamausteseos','Apple spice mix'],[1.5,'dl','Kuohukerma','Whipping cream'],[44,'g','Tomusokeri','Icing sugar'],[0.5,'tl','Vanilja-aromi','Vanilla extract'],[2,'kpl','Liivatelehti','Gelatine sheet']],s:[['Keitä kinuski (fariinisokeri + kuohukerma) paksuhkoksi. Anna jäähtyä.','Cook the toffee (brown sugar + cream) until thickish. Let cool.'],['Vatkaa tuorejuusto ja sokeri yhteen. Lisää jäähtynyt kinuski ja mausteseos.','Beat the cream cheese and sugar. Add the cooled toffee and spice mix.'],['Liota liivatteet. Vaahdota kerma, tomusokeri ja vanilja paksuksi vaahdoksi.','Soak the gelatine. Whip the cream, icing sugar and vanilla thick.'],['Kääntele kermavaahto hellästi tuorejuuston joukkoon. Sulata liivatteet kermatilkkaan ja lisää massaan.','Fold the cream gently into the cream cheese. Melt the gelatine in a splash of cream and add.'],['Kaada mousse blondiepohjien päälle ja tasoita pinta. Pakasta.','Pour the mousse on the blondie bases and smooth the top. Freeze.']]}]},
{id:'britakakku',c:'kakku',n:['Britakakku (gluteeniton)','Brita cake (gluten-free)'],f:'2275',note:['1× = 6 peltiä. Paperissa myös 8, 10 ja 12 peltiä. Käsin: pistaasia 1000 g / 10 peltiä.','1× = 6 trays. Paper also has 8, 10 and 12 trays. By hand: pistachios 1000 g per 10 trays.'],p:[{t:['Pohja','Base'],i:[[870,'g','Voi','Butter'],[700,'g','Sokeri','Sugar'],[14,'kpl','Keltuainen','Egg yolk'],[600,'g','Gluteeniton jauho','Gluten-free flour'],[300,'g','Mantelijauhe','Almond flour'],[40,'g','Leivinjauhe','Baking powder'],[7,'dl','Maito','Milk']],s:[['Vaahdota voi ja sokeri.','Cream the butter and sugar.'],['Lisää keltuaiset yksitellen joukkoon.','Add the yolks one at a time.'],['Lisää sekoitetut kuivat aineet vuorotellen maidon kanssa ja sekoita nopeasti sekaisin.','Add the mixed dry ingredients in turns with the milk and mix quickly.'],['Levitä leivinpaperoiduille pelleille.','Spread onto lined trays.']]},{t:['Marenki','Meringue'],i:[[14,'kpl','Valkuainen','Egg white'],[1000,'g','Sokeri','Sugar'],[25,'g','Vaniljasokeri','Vanilla sugar'],[null,'','Mantelilastut (tai pistaasi)','Flaked almonds (or pistachios)']],s:[['Vatkaa valkuaiset, sokeri ja vaniljasokeri marengiksi ja levitä pohjien päälle.','Whisk the egg whites, sugar and vanilla sugar to a meringue and spread on the bases.'],['Ripottele päälle mantelilastuja.','Sprinkle flaked almonds on top.'],['Paista 165 °C n. 10–15 min.','Bake at 165 °C for about 10–15 min.']]}]},
{id:'gluteeniton-focaccia',c:'taikina',n:['Gluteeniton focaccia','Gluten-free focaccia'],v:1,f:'2276',note:['1× = 2 pientä Ikean metallivuokaa. Käsin 4 kpl = 2×.','1× = 2 small IKEA metal tins. By hand 4 tins = 2×.'],p:[{i:[[7.5,'dl','Vesi','Water'],[23,'g','Kuivahiiva','Dry yeast'],[3,'tl','Psyllium','Psyllium'],[3,'rkl','Oliiviöljy','Olive oil'],[2,'tl','Suola','Salt'],[2,'tl','Sokeri','Sugar'],[200,'g','Tumma gluteeniton jauhoseos','Dark gluten-free flour mix'],[600,'g','Vaalea gluteeniton jauhoseos','Light gluten-free flour mix'],[null,'','Öljy, sormisuola ja kuivatut yrtit pinnalle','Oil, flake salt and dried herbs for the top']],s:[['Mittaa veden joukkoon hiiva ja psyllium ja anna turvota 10 min.','Add the yeast and psyllium to the water and let swell 10 min.'],['Lisää suola, sokeri ja öljy.','Add the salt, sugar and oil.'],['Lisää jauhot ja vaivaa lapavatkaimella reilu 5 min.','Add the flours and mix with the paddle for a good 5 min.'],['Leivinpaperoi ja öljyä vuoat. Jaa taikina vuokiin ja painele tasaiseksi. Laita pinnalle öljyä, sormisuolaa ja kuivattuja yrttejä.','Line and oil the tins. Divide the dough and press flat. Top with oil, flake salt and dried herbs.'],['Nostata peitettynä, kunnes kohonnut vuoan reunojen tasolle.','Prove covered until risen to the tin edges.'],['Paista 200 °C n. 20 min. Ota pois vuoasta heti uunista tultua.','Bake at 200 °C for about 20 min. Take out of the tins right after baking.']]}]},
{id:'tintan-suklaakakku',c:'kakku',n:['Tintån suklaakakku','Tintå chocolate cake'],f:'2277',note:['1× = 10 kpl 24 cm kakkua. 14 kpl = 1,4×. Tumma vetopohja pohjaksi ja kanneksi.','1× = 10 cakes of 24 cm. 14 cakes = 1.4×. Dark sponge sheet as base and lid.'],p:[{t:['Mousse ja kasaus (10 × 24 cm)','Mousse and assembly (10 × 24 cm)'],i:[[1200,'g','Tumma suklaa','Dark chocolate'],[2400,'g','Voi','Butter'],[1000,'g','Kaakaojauhe','Cocoa powder'],[1300,'g','Keltuainen','Egg yolk'],[800,'g','Sokeri (keltuaisille)','Sugar (for the yolks)'],[2166,'g','Valkuainen','Egg white'],[800,'g','Sokeri (valkuaisille)','Sugar (for the whites)'],[2.6,'l','Kuohukerma','Whipping cream'],[1.5,'dl','Kuohukerma liivatteille','Whipping cream for the gelatine'],[32,'kpl','Liivatelehti','Gelatine sheet'],[1,'l','Kahvi','Coffee'],[1,'dl','Kahlua','Kahlua'],[null,'','Tumma vetopohja (pohjaksi ja kanneksi)','Dark sponge sheet (for base and lid)']],s:[['Leikkaa vetopohjat vuoan kokoisiksi ympyröiksi. Pohjapalojen ei tarvitse olla kokonaisia.','Cut the sponge sheets into tin-sized circles. The base pieces do not need to be whole.'],['Asettele pohjapalat hyvin voideltuihin kakkuvuokiin ja kostuta kahlua-kahvilla. Jätä puolet kahvista kansien kostutukseen.','Put the base pieces in well-greased tins and soak with Kahlua coffee. Keep half of the coffee for the lids.'],['Sulata voi, lisää suklaa ja anna sulaa. Siivilöi lämpimään seokseen kaakaojauhe.','Melt the butter, add the chocolate and let it melt. Sift the cocoa into the warm mix.'],['Vaahdota kerma ja nosta kylmään odottamaan.','Whip the cream and chill.'],['Vaahdota keltuainen ja toinen sokeri pienemmässä padassa.','Whisk the yolks with one portion of sugar in the smaller bowl.'],['Liota liivatteet. Kun pehmenneet, purista vesi pois ja sulata pienempään määrään kuumennettua kermaa.','Soak the gelatine. When soft, squeeze and melt in the smaller amount of hot cream.'],['Vaahdota valkuaiset ja loppu sokeri isossa padassa.','Whisk the egg whites with the rest of the sugar in the big bowl.'],['Yhdistä munavaahdot, lisää voi-suklaaseos, lisää liivatekerma ja lopuksi vaahdotettu kerma. Kaikki sekoitetaan käsin.','Combine the egg foams, add the butter-chocolate, the gelatine cream and finally the whipped cream. Mix everything by hand.'],['Jaa mousse vuokiin pohjien päälle ja paina kansipalat mousseen. Kostuta lopulla kahlua-kahvilla.','Divide the mousse over the bases and press the lids on top. Soak with the rest of the Kahlua coffee.']]}]},
{id:'hapanjuurileipa',c:'taikina',n:['Hapanjuurileipä','Sourdough bread'],v:1,f:'2278',note:['1× = 1 leipä (n. 950 g). Käsin 5 leivän määrät (5×).','1× = 1 loaf (about 950 g). By hand amounts for 5 loaves (5×).'],p:[{i:[[250,'g','Manitoba-jauho','Manitoba flour'],[250,'g','Vehnäjauho','Wheat flour'],[350,'g','Viileä vesi','Cool water'],[100,'g','Aktiivinen juuri','Active sourdough starter'],[8,'g','Maldon-sormisuola','Maldon flake salt']],s:[['Sekoita jauhot keskenään. Sekoita vesi ja juuri ja lisää jauhoihin. Sekoita taikinaksi. Lepo 30 min.','Mix the flours. Mix the water and starter and add to the flour. Mix to a dough. Rest 30 min.'],['Lisää suola sekoittaen tai taittaen. Lepo 30 min.','Add the salt by mixing or folding. Rest 30 min.'],['Taittele 3 kertaa 30 min välein.','Fold 3 times, 30 min apart.'],['Viimeisen taittelun jälkeen anna nousta huoneenlämmössä 3–6 tuntia.','After the last fold, let rise at room temperature for 3–6 hours.'],['Muotoile leiviksi. Nosta liinalla peitettyyn ja jauhotettuun nostatuskoriin, peitä muovipussilla ja nosta kylmiöön seuraavaan päivään.','Shape into loaves. Put in a floured, cloth-lined proving basket, cover with a plastic bag and put in the cold room until the next day.'],['Paisto: nosta syvä GN-pakki uuniin ja esilämmitä uuni pakin kanssa 250 °C:een. Leikkaa foliopala valmiiksi.','Baking: put a deep GN tray in the oven and preheat with it to 250 °C. Cut a piece of foil ready.'],['Kumoa leipä leivinpaperille, tee viillot ja nosta paperin kanssa kuumaan pakkiin. Laita folio tiukasti päälle.','Turn the bread onto baking paper, score it and lift it with the paper into the hot tray. Cover tightly with foil.'],['Paista 250 °C 20 min.','Bake at 250 °C for 20 min.'],['Avaa folio ja jatka paistoa 210 °C 20 min.','Remove the foil and bake at 210 °C for 20 more min.'],['Nosta leipä ritilälle jäähtymään.','Cool the bread on a rack.']]}]},
{id:'limepiirakka',c:'kakku',n:['Limepiirakka (Key lime pie) ja italialainen marenki','Key lime pie and Italian meringue'],f:'2279',note:['Täyte 1× = 1 kpl 26 cm. 4 kpl = 4×, 6 kpl Blanko ≈ 4,9×, 15 kpl Blanko ≈ 12,2×. Marengista saa 1 pyöreän tai 2 blankoa; käsin 540 g / 135 g / 9 kpl.','Filling 1× = one 26 cm pie. 4 = 4×, 6 Blanko ≈ 4.9×, 15 Blanko ≈ 12.2×. The meringue covers 1 round or 2 Blanko; by hand 540 g / 135 g / 9 pcs.'],p:[{t:['Limetäyte (1 × 26 cm)','Lime filling (1 × 26 cm)'],i:[[60,'g','Keltuainen','Egg yolk'],[1,'kpl','Limen kuori','Lime zest'],[1,'tlk','Kondensoitu maito','Condensed milk'],[120,'ml','Limemehu','Lime juice'],[60,'g','Ranskankerma','Crème fraîche']],s:[['Vatkaa keltuaiset ja limenkuori sekaisin. Lisää kondensoitu maito, limemehu ja lopuksi ranskankerma.','Whisk the yolks and lime zest. Add the condensed milk, lime juice and finally the crème fraîche.'],['Anna täytteen tekeytyä 15 min ennen paistoa.','Let the filling rest 15 min before baking.'],['Jaa täyte murotaikinapohjille ja paista 160 °C 15 min.','Divide into shortcrust bases and bake at 160 °C for 15 min.']]},{t:['Italialainen marenki','Italian meringue'],i:[[250,'g','Sokeri','Sugar'],[60,'g','Vesi','Water'],[4,'kpl','Valkuainen','Egg white']],s:[['Mittaa sokeri ja vesi kattilaan. Laita valkuaiset vaahtoutumaan.','Put the sugar and water in a pot. Start whisking the egg whites.'],['Keitä sokerivesi 120 °C:een valkuaisten vaahtoutuessa. Älä sekoita missään vaiheessa!','Boil the syrup to 120 °C while the whites whisk. Do not stir it at any point!'],['Kaada kuuma sokeriliemi ohuena nauhana kovaksi vaahdotettujen valkuaisten joukkoon samalla vaahdottaen.','Pour the hot syrup in a thin stream into the stiff whites while whisking.'],['Jatka vaahdottamista, kunnes kulhon pohja ei tunnu enää kuumalta ja marenki on selvästi paksuuntunut.','Keep whisking until the bowl bottom no longer feels hot and the meringue is clearly thick.']]}]},
{id:'biscoff-mutakakku',c:'kakku',n:['Biscoff-mutakakku','Biscoff mud cake'],v:1,f:'2280',note:['1× = 8 pitkää irtopohjavuokaa tai 4 kpl 26 cm. Biscoff-määrä on muutettu käsin 1600 g:ksi. Käsin myös 3 kpl määrät (0,75×).','1× = 8 long springform tins or four 26 cm. The Biscoff amount was changed by hand to 1600 g. Also 3-tin amounts by hand (0.75×).'],p:[{i:[[1600,'g','Biscoff creamy -levite','Biscoff creamy spread'],[7,'dl','Vesi','Water'],[240,'g','Vaalea balsamicokastike','White balsamic glaze'],[1200,'g','Sokeri','Sugar'],[4,'tl','Suola','Salt'],[8,'tl','Vaniljasokeri','Vanilla sugar'],[8,'tl','Leivinjauhe','Baking powder'],[1224,'g','Vehnäjauho','Wheat flour']],s:[['Poraa Biscoff, vesi ja balsamico keskenään tasaiseksi.','Blend the Biscoff, water and balsamic smooth.'],['Sekoita kuivat keskenään ja sekoita yhteen Biscoff-massan kanssa.','Mix the dry ingredients and combine with the Biscoff mix.'],['Laita leivinpaperi vuokien pohjalle ja jaa taikina vuokiin.','Line the tin bottoms with paper and divide the batter.'],['Paista 180 °C 15 min.','Bake at 180 °C for 15 min.']]}]},
{id:'patonki',c:'taikina',n:['Patonki','Baguette'],v:1,f:'2281',note:['1× = 2 l vettä. 3 l = 1,5× ja 4 l = 2×. Sormisuola on muutettu käsin (2 l: 70 g). Palapaino 430–450 g.','1× = 2 l water. 3 l = 1.5× and 4 l = 2×. Flake salt changed by hand (2 l: 70 g). Piece weight 430–450 g.'],p:[{i:[[2,'l','Vesi (kylmä)','Water (cold)'],[2400,'g','Vehnäjauho','Wheat flour'],[100,'g','Kaurahiutale','Oat flakes'],[160,'g','Siemenet','Seeds'],[50,'g','Kuivahiiva','Dry yeast'],[70,'g','Sormisuola','Flake salt'],[140,'g','Tumma siirappi','Dark syrup']],s:[['Sekoita kaikki aineet pataan ja vaivaa taikinaksi.','Mix everything in the bowl and knead to a dough.'],['Palapaino 430–450 g. Esilämmitä uuni 250 °C:een.','Piece weight 430–450 g. Preheat the oven to 250 °C.'],['Pyörittele palat patongeiksi ja nostata hyvin ennen paistoa.','Roll the pieces into baguettes and prove well before baking.'],['Pienennä lämpö 200 °C:een. Höyryä yksi painallus.','Lower to 200 °C. One press of steam.'],['Paista 200 °C n. 22–23 min.','Bake at 200 °C for about 22–23 min.']]}]},
{id:'focaccia',c:'taikina',n:['Focaccia','Focaccia'],v:1,f:'2282',note:['1× = 1 l vettä. Paperissa 1,5 l, 2 l ja 3 l. Teipissä 3 l Bahn mi -patonki: vehnäjauho n. 2200 g + Manitoba n. 2200 g, kuivahiiva 90 g, suola 120 g, oliiviöljy 162 g, palapaino 450 g, paisto 180 °C 16–17 min, ei höyrytystä.','1× = 1 l water. Paper has 1.5 l, 2 l and 3 l. Tape: 3 l Bahn mi baguette: wheat flour about 2200 g + Manitoba about 2200 g, dry yeast 90 g, salt 120 g, olive oil 162 g, piece 450 g, bake 180 °C 16–17 min, no steam.'],p:[{i:[[1,'l','Vesi (viileä)','Water (cool)'],[54,'g','Oliiviöljy','Olive oil'],[1600,'g','Vehnäjauho','Wheat flour'],[30,'g','Kuivahiiva','Dry yeast'],[40,'g','Suola','Salt'],[null,'','Oliiviöljy, sormisuola ja kuivatut yrtit pinnalle','Olive oil, flake salt and dried herbs for the top']],s:[['Sekoita kaikki raaka-aineet pataan.','Put everything in the bowl.'],['Vaivaa ainakin 20 min, ensin nopeudella 1 ja sitten 2. HUOM! Jauhoja saattaa tarvita lisää alussa, jos taikina ei lähde muodostumaan.','Knead at least 20 min, first on speed 1 then 2. NOTE: you may need more flour at the start if the dough will not come together.'],['Voitele pakit oliiviöljyllä. Focaccian päälle oliiviöljy, sormisuola ja kuivatut yrtit.','Oil the trays. Top the focaccia with olive oil, flake salt and dried herbs.'],['Palapainot: iso alumiinivuoka 1500–1600 g, GN-pakki 1300–1400 g, leipä 700–800 g, patonki 400–500 g. Kohota höyryssä.','Piece weights: big aluminium tray 1500–1600 g, GN tray 1300–1400 g, loaf 700–800 g, baguette 400–500 g. Prove in steam.'],['Paista focacciat 180 °C n. 25–30 min, leivät 175 °C n. 30 min ja patongit 180 °C 20–25 min.','Bake focaccia at 180 °C for about 25–30 min, loaves at 175 °C about 30 min and baguettes at 180 °C 20–25 min.']]}]},
{id:'valkosuklaakeksit',c:'leivos',n:['Valkosuklaakeksit','White chocolate biscuits'],f:'2283',note:['Keksi 90 g.','Cookie 90 g.'],p:[{i:[[585,'g','Voi, pehmeä','Butter, soft'],[397,'g','Kondensoitu maito (1 prk)','Condensed milk (1 can)'],[619,'g','Vehnäjauho','Wheat flour'],[20,'g','Leivinjauhe','Baking powder'],[5,'dl','Valkosuklaa','White chocolate']],s:[['Vaahdota voi valkeaksi vaahdoksi, lisää kondensoitu maito ja vaahdota vielä lisää.','Beat the butter pale and fluffy, add the condensed milk and beat more.'],['Lisää jauhot ja sekoita vain sekaisin. Lisää lopuksi suklaa.','Add the flour and mix only until combined. Finally add the chocolate.'],['Punnaa taikinasta 90 g kasoja ja pakkaa leivosrasiaan.','Weigh 90 g mounds and pack them in a pastry box.'],['Paisto: anna sulaa hieman ennen paistoa. 160 °C 15 min.','Baking: let thaw a little first. 160 °C for 15 min.']]}]},
{id:'pannacottakakku',c:'kakku',n:['Pannacottakakku (gluteeniton)','Panna cotta cake (gluten-free)'],f:'2284',note:['1× = 1 kakku (24 cm). 3 kakkua = 3×. Käsin 2× määrät (liivate 9 kpl) ja vaniljatanko (3 kpl / 3 kakkua).','1× = 1 cake (24 cm). 3 cakes = 3×. By hand 2× amounts (gelatine 9) and vanilla pod (3 per 3 cakes).'],p:[{t:['Pohja','Base'],i:[[200,'g','Gluteeniton digestive','Gluten-free digestive'],[100,'g','Voi, sulatettu','Butter, melted']],s:[['Murskaa keksit ja sekoita joukkoon sula voi. Painele 24 cm leivinpaperoidun vuoan pohjalle ja reunoille.','Crush the biscuits and mix in the melted butter. Press into the bottom and sides of a lined 24 cm tin.']]},{t:['Pannacotta','Panna cotta'],i:[[4.5,'kpl','Liivatelehti','Gelatine sheet'],[216,'g','Valkosuklaa','White chocolate'],[432,'g','Kuohukerma','Whipping cream'],[432,'ml','Turkkilainen jogurtti','Turkish yogurt'],[13.5,'g','Vaniljasokeri','Vanilla sugar'],[1,'kpl','Vaniljatanko','Vanilla pod']],s:[['Laita liivatteet likoamaan.','Soak the gelatine.'],['Kuumenna kerma höyryäväksi, lisää puristetut liivatteet ja sitten valkosuklaa.','Heat the cream until steaming, add the squeezed gelatine and then the white chocolate.'],['Jos kermaseos on todella kuumaa, anna sen jäähtyä hieman. Sekoita joukkoon jogurtti ja vaniljasokeri.','If very hot, let it cool a little. Stir in the yogurt and vanilla sugar.'],['Kaada massa keksipohjan päälle. Anna hyytyä kylmiössä.','Pour onto the biscuit base. Let it set in the cold room.']]}]},
{id:'pistaasijaatelo-sandwich',c:'jaatelo',n:['Pistaasijäätelösandwich','Pistachio ice cream sandwich'],v:1,f:'2285',note:['N. 20 annosta. Keksinä pistaasikeksit (vegaani).','About 20 portions. Use the vegan pistachio cookies.'],p:[{i:[[2,'prk','Oddlygood vispi','Oddlygood whipping cream'],[320,'g','Kondensoitu kookosmaito','Condensed coconut milk'],[42,'g','Glukoosisiirappi','Glucose syrup'],[140,'g','Vegaaninen mascarpone','Vegan mascarpone'],[140,'g','Pistaasitahna','Pistachio paste'],[1,'tl','Suola','Salt'],[null,'','Pistaasikeksit','Pistachio cookies'],[null,'','Veitsellä leikatut pistaasit','Knife-chopped pistachios']],s:[['Sekoita keskenään kondensoitu kookosmaito ja glukoosi.','Mix the condensed coconut milk and glucose.'],['Sekoita keskenään mascarpone, pistaasitahna ja suola.','Mix the mascarpone, pistachio paste and salt.'],['Vaahdota vispi kovaksi vaahdoksi.','Whip the cream to stiff peaks.'],['Lisää kookosseos ja lopuksi pistaasiseos varovasti. Vältä kovaa vatkaamista.','Add the coconut mix and finally the pistachio mix gently. Avoid hard whisking.'],['Pussita ja laita kylmään kovettumaan.','Put into a piping bag and chill to firm up.'],['Pursota pistaasikeksin päälle 45–50 g, enemmän massaa toiselle puolelle.','Pipe 45–50 g on a pistachio cookie, more on one side.'],['Paina paksumpi sivu veitsellä leikattuihin pistaasipähkinöihin.','Press the thicker side into chopped pistachios.'],['Laita pakastimeen ja pakkaa krokopusseihin, kun jäätelö on kovettunut.','Freeze and pack in bags once the ice cream is firm.']]}]},
{id:'mausteseokset',c:'koriste',n:['Pumpkin spice ja piparkakkumausteseos','Pumpkin spice and gingerbread spice mix'],v:1,f:'2286',p:[{t:['Pumpkin spice','Pumpkin spice'],i:[[1.33,'rkl','Kaneli (1 1/3 rkl)','Cinnamon (1 1/3 tbsp)'],[1,'tl','Inkivääri','Ginger'],[1,'tl','Muskottipähkinä','Nutmeg'],[0.5,'tl','Neilikka','Cloves'],[0.5,'tl','Maustepippuri','Allspice']],s:[['Sekoita mausteet keskenään ja säilytä kannellisessa purkissa.','Mix the spices and keep in a lidded jar.']],gen:1},{t:['Piparkakkumausteseos','Gingerbread spice mix'],i:[[4,'tl','Kaneli','Cinnamon'],[2,'tl','Inkivääri','Ginger'],[2,'tl','Neilikka','Cloves'],[1,'tl','Pomeranssinkuori','Bitter orange peel'],[0.5,'tl','Kardemumma','Cardamom']],s:[['Sekoita mausteet keskenään ja säilytä kannellisessa purkissa.','Mix the spices and keep in a lidded jar.']],gen:1}]},
{id:'piirakkatayte-creme-vanille',c:'kreemi',n:['Piirakkatäyte (crème vanille)','Pie custard filling (crème vanille)'],f:'2287',p:[{i:[[397,'g','Kondensoitu maito','Condensed milk'],[150,'g','Maito','Milk'],[2,'kpl','Kananmuna','Egg'],[1,'kpl','Vaniljatanko','Vanilla pod']],s:[['Sekoita ainekset sekaisin ja täytä haluamasi piirakka, esim. mustikka, omena, päärynä tai vadelma.','Mix everything and fill the pie you want, e.g. blueberry, apple, pear or raspberry.'],['Paista 170 °C (kiertoilma) n. 40 min, kunnes hyytynyt.','Bake at 170 °C (fan) for about 40 min until set.']]}]},
{id:'mango-passion-mascarpone',c:'kakku',n:['Mango-passionmascarponekakku','Mango-passion mascarpone cake'],f:'2288',note:['1× = 4 kakkua. Käsin muutettu: tomusokeri 700 g, mangopyree 300 g, passionpyree 350 g. Teipissä myös ×1 ja ×3 määrät, jotka eivät täsmää täysin (tarkista).','1× = 4 cakes. Changed by hand: icing sugar 700 g, mango purée 300 g, passion purée 350 g. The tape also has ×1 and ×3 amounts that do not fully match (check).'],p:[{t:['Pohja','Base'],i:[[800,'g','Digestive-keksit','Digestive biscuits'],[300,'g','Voi','Butter']],s:[['Murskaa keksit ja sulata voi, sekoita keskenään ja painele vuoan pohjalle.','Crush the biscuits, melt the butter, mix and press into the tin bottom.']]},{t:['Mousse','Mousse'],i:[[2000,'g','Kuohukerma','Whipping cream'],[1600,'g','Mascarpone','Mascarpone'],[700,'g','Tomusokeri','Icing sugar'],[60,'g','Vaniljasokeri','Vanilla sugar'],[300,'g','Mangopyree','Mango purée'],[16,'kpl','Liivatelehti','Gelatine sheet'],[350,'g','Passionpyree','Passion fruit purée']],s:[['Sulata ensin pyreet erikseen. Liota liivatteet.','First thaw the purées separately. Soak the gelatine.'],['Vaahdota kerma vaahdoksi.','Whip the cream.'],['Sulata liivatteet kuumaan passionpyreeseen ja yhdistä mangopyreen joukkoon.','Melt the gelatine in the hot passion purée and combine with the mango purée.'],['Vatkaa mascarpone ja sokerit sekaisin, lisää pyree.','Beat the mascarpone and sugars, add the purée.'],['Sekoita lopuksi vaahdotettu kerma joukkoon. Jaa massa keksipohjien päälle.','Finally fold in the whipped cream. Spread on the biscuit bases.']]}]},
{id:'omenajuustokakku',c:'kakku',n:['Omenajuustokakku','Apple cheesecake'],f:'2289',note:['1× = 4 kakkua (24 cm).','1× = 4 cakes (24 cm).'],p:[{t:['Pohja','Base'],i:[[800,'g','Biscoff-keksit','Biscoff biscuits'],[300,'g','Voi, sulatettu','Butter, melted']],s:[['Murskaa keksit ja sekoita voin kanssa. Painele 24 cm leivinpaperoidun vuoan pohjalle ja reunoille.','Crush the biscuits and mix with the butter. Press into the bottom and sides of lined 24 cm tins.']]},{t:['Juustomassa','Cheese filling'],i:[[2400,'g','Tuorejuusto','Cream cheese'],[600,'g','Ranskankerma','Crème fraîche'],[720,'g','Sokeri','Sugar'],[40,'g','Maizena','Cornflour'],[20,'g','Vaniljasokeri','Vanilla sugar'],[12,'kpl','Kananmuna','Egg']],s:[['Ota tuorejuusto ja ranskankerma ajoissa huoneenlämpöön.','Bring the cream cheese and crème fraîche to room temperature in time.'],['Sekoita aineet sekaisin ja kaada keksipohjan päälle.','Mix everything and pour onto the biscuit base.']]},{t:['Omenat','Apples'],i:[[10,'kpl','Omena, kuutioitu (8–12 kpl)','Apples, diced (8–12)'],[60,'g','Sokeri','Sugar'],[1.33,'rkl','Kaneli (1 1/3 rkl)','Cinnamon (1 1/3 tbsp)']],s:[['Kuutioi omenat ja sekoita joukkoon sokeri ja kaneli. Laita juustokakkumassan pintaan.','Dice the apples and mix with the sugar and cinnamon. Put on top of the cheese filling.']]},{t:['Murupinta','Crumble topping'],i:[[200,'g','Voi, sulatettu','Butter, melted'],[105,'g','Kaurahiutaleet','Oat flakes'],[130,'g','Vehnäjauho','Wheat flour'],[140,'g','Fariinisokeri','Brown sugar']],s:[['Sekoita kaikki aineet ja ripottele kakun pinnalle ennen paistoa.','Mix everything and sprinkle on the cake before baking.'],['Paista 160 °C 60–75 min, puhallukset pois.','Bake at 160 °C for 60–75 min with the fan off.'],['Sammuta uuni ja anna olla jälkilämmössä 60 min.','Turn off the oven and leave in the residual heat for 60 min.']]}]},
{id:'cookie-dough',c:'leivos',n:['Cookie dough (vegaani)','Cookie dough (vegan)'],v:1,f:'2290',note:['Paperissa käsin 1,5× määrät.','Paper has 1.5× amounts by hand.'],p:[{i:[[1000,'g','Vehnäjauho','Wheat flour'],[440,'g','Margariini','Margarine'],[500,'g','Fariinisokeri','Brown sugar'],[500,'g','Sokeri','Sugar'],[300,'g','Kaurakerma','Oat cream'],[4,'tl','Vanilja-aromi','Vanilla extract'],[2,'tl','Suola','Salt'],[500,'g','Tumma suklaa','Dark chocolate']],s:[['Kypsennä ensin jauhot 100 °C uunissa, kunnes lämpötila on vähintään 70 °C. Anna jäähtyä.','First heat-treat the flour in a 100 °C oven until it reaches at least 70 °C. Let cool.'],['Vatkaa margariini ja sokerit vaahdoksi, lisää vanilja-aromi, kaurakerma ja suola.','Beat the margarine and sugars fluffy, add the vanilla, oat cream and salt.'],['Sekoita joukkoon kypsennetyt jauhot ja lopuksi rouhittu tumma suklaa.','Mix in the heat-treated flour and finally the chopped dark chocolate.'],['Pyöritä käsin pakkiin tai laatikkoon nokareita ja pakasta.','Roll small lumps by hand into a box and freeze.']]}]},
{id:'vegaanimarenki',c:'kreemi',n:['Vegaanimarenki (paistettu)','Vegan meringue (baked)'],v:1,f:'2291',p:[{i:[[3,'dl','Kikherneliemi','Chickpea liquid'],[5,'dl','Sokeri','Sugar'],[1,'tl','Viinikivi','Cream of tartar']],s:[['Vaahdota kikherneliemi valkeaksi vaahdoksi.','Whisk the chickpea liquid to a white foam.'],['Lisää sokeria pikkuhiljaa koko ajan vatkaten.','Add the sugar little by little while whisking.'],['Kun kaikki sokeri on lisätty ja marenki on muodostunut, lisää viinikivi.','When all the sugar is in and the meringue has formed, add the cream of tartar.'],['Vatkaa niin kauan, että sokeri on sulanut ja marenki on kovaa.','Whisk until the sugar has dissolved and the meringue is stiff.'],['Paista 100 °C 2,5 tuntia. Sammuta uuni, avaa ovi raolleen ja jätä marengit kuivumaan jälkilämpöön 30 min.','Bake at 100 °C for 2.5 hours. Turn off the oven, open the door a crack and leave to dry in the residual heat for 30 min.'],['Pakkaa marengit kerroksittain kuivaan ja puhtaaseen muoviastiaan leivinpaperit väliin. Älä laita kantta. Säilytä kuivavälikössä, jossa ei ole rasvaa.','Pack in layers in a dry, clean plastic box with baking paper between. Do not put a lid on. Keep in the dry store away from grease.']]}]},
{id:'gluteeniton-siemennakkileipa',c:'taikina',n:['Gluteeniton siemennäkkileipä','Gluten-free seed crispbread'],v:1,f:'2292',note:['1× = 1 pellillinen. 4 ja 8 pellillistä = 4× ja 8×. Maissijauho 2 dl = 140 g.','1× = 1 tray. 4 and 8 trays = 4× and 8×. Corn flour 2 dl = 140 g.'],p:[{i:[[140,'g','Maissijauho (2 dl)','Corn flour (2 dl)'],[0.75,'dl','Auringonkukansiemen','Sunflower seeds'],[0.5,'dl','Pellavansiemen','Flaxseeds'],[0.5,'dl','Seesaminsiemen','Sesame seeds'],[0.5,'dl','Kurpitsansiemen','Pumpkin seeds'],[0.5,'dl','Oliiviöljy','Olive oil'],[2.5,'dl','Kiehuva vesi','Boiling water'],[null,'','Sormisuola päälle','Flake salt on top']],s:[['Sekoita kuivat aineet keskenään.','Mix the dry ingredients.'],['Sekoita vesi ja öljy joukkoon ja anna hetken turvota.','Mix in the water and oil and let swell a moment.'],['Levitä pellille ja ripottele sormisuolaa päälle.','Spread on a tray and sprinkle flake salt on top.'],['Paista 150 °C ensin 10 min ja leikkaa levy pitsaleikkurilla halutuiksi paloiksi.','Bake at 150 °C for 10 min first, then cut into pieces with a pizza cutter.'],['Paista 150 °C vielä noin 50 min.','Bake at 150 °C for about 50 more min.']]}]},
{id:'muropiirakat',c:'leivos',n:['Muropiirakat','Jam shortbread tarts'],f:'2293',note:['1× = 24 kpl.','1× = 24 pcs.'],p:[{i:[[454,'g','Voi, pehmeä','Butter, soft'],[400,'g','Sokeri','Sugar'],[2,'tl','Vanilja-aromi','Vanilla extract'],[5,'g','Suola','Salt'],[438,'g','Vehnäjauho','Wheat flour'],[168,'g','Mantelijauhe','Almond flour'],[null,'','Hillo','Jam']],s:[['Vaahdota voi ja sokeri, lisää vanilja ja suola.','Cream the butter and sugar, add the vanilla and salt.'],['Lisää lopuksi jauhot.','Finally add the flours.'],['Jaa taikina puoliksi ja laita toinen puoli kylmään.','Halve the dough and chill one half.'],['Punnaa 30 g taikinaa rasvattujen tartalettivuokien pohjalle ja painele.','Press 30 g dough into the bottom of each greased tartlet mould.'],['Paista pohjia 160 °C 6 min.','Bake the bases at 160 °C for 6 min.'],['Kun pohjat ovat jäähtyneet, pursota hilloa pohjille ja murusta lopputaikinasta 30 g per vuoka hillon päälle.','When cool, pipe jam onto the bases and crumble 30 g of the remaining dough over each.'],['Jatka paistamista 160 °C 18 min.','Bake on at 160 °C for 18 min.']]}]},
{id:'brownie-cookies',c:'leivos',n:['Brownie cookies (gluteeniton)','Brownie cookies (gluten-free)'],f:'2294',note:['Keksi n. 90 g.','Cookie about 90 g.'],p:[{i:[[435,'g','Tomusokeri','Icing sugar'],[75,'g','Kaakaojauhe','Cocoa powder'],[4.5,'g','Suola','Salt'],[132,'g','Valkuainen (4 kpl)','Egg white (4 pcs)'],[1,'tl','Vanilja-aromi','Vanilla extract'],[3.6,'dl','Tumma suklaa','Dark chocolate'],[3.6,'dl','Pähkinä, rouhittu','Nuts, chopped']],s:[['Sekoita ensin yhteen kaikki muut paitsi suklaa ja pähkinät. Lisää ne lopuksi.','First mix everything except the chocolate and nuts. Add them last.'],['Punnaa pellille n. 90 g kasoja ja paista 175 °C 13 min.','Weigh about 90 g mounds onto a tray and bake at 175 °C for 13 min.']]}]},
{id:'maapahkinavoicookies',c:'leivos',n:['Maapähkinävoicookies','Peanut butter cookies'],f:'2295',note:['Keksi 70–75 g.','Cookie 70–75 g.'],p:[{i:[[230,'g','Voi','Butter'],[350,'g','Maapähkinävoi','Peanut butter'],[450,'g','Fariinisokeri','Brown sugar'],[250,'g','Sokeri','Sugar'],[2,'kpl','Kananmuna','Egg'],[2,'kpl','Keltuainen','Egg yolk'],[425,'g','Vehnäjauho','Wheat flour'],[4,'tl','Vaniljasokeri','Vanilla sugar'],[1,'tl','Ruokasooda','Baking soda'],[1,'tl','Suola','Salt'],[200,'g','Kaurahiutale','Oat flakes'],[200,'g','Maitosuklaarouhe','Chopped milk chocolate'],[100,'g','Valkosuklaarouhe','Chopped white chocolate']],s:[['Sulata voi ja maapähkinävoi, lisää sokerit ja sekoita tasaiseksi. Anna jäähtyä.','Melt the butter and peanut butter, add the sugars and mix smooth. Let cool.'],['Lisää kananmunat ja keltuaiset yksitellen.','Add the eggs and yolks one at a time.'],['Lisää keskenään sekoitetut kuivat aineet ja lopuksi suklaarouheet.','Add the mixed dry ingredients and finally the chopped chocolate.'],['Punnitse 70–75 g palloja ja muotoile kekseiksi.','Weigh 70–75 g balls and shape into cookies.'],['Paista 160 °C n. 10 min.','Bake at 160 °C for about 10 min.']]}]},
{id:'gua-bao',c:'taikina',n:['Gua bao -höyrysämpylä','Gua bao steamed bun'],v:1,f:'2296',note:['1× = 2 l vettä, n. 70 kpl. 3 l = 1,5× (n. 105 kpl), 4 l = 2× (n. 140 kpl). Käsin 2,5 l määrät. Teipissä: Carte-paino 30 g, paisto 5 min.','1× = 2 l water, about 70 pcs. 3 l = 1.5× (about 105), 4 l = 2× (about 140). By hand 2.5 l amounts. Tape: Carte weight 30 g, steam 5 min.'],p:[{i:[[2,'l','Vesi','Water'],[30,'g','Kuivahiiva','Dry yeast'],[140,'g','Rypsiöljy','Rapeseed oil'],[3750,'g','Vehnäjauho','Wheat flour'],[280,'g','Sokeri','Sugar'],[70,'g','Leivinjauhe','Baking powder'],[50,'g','Suola','Salt']],s:[['Lämmitä vesi kädenlämpöiseksi. Lisää hiiva ja öljy.','Warm the water to hand temperature. Add the yeast and oil.'],['Sekoita kuivat aineet pataan.','Put the dry ingredients in the bowl.'],['Lisää vesi nauhana koneen pyöriessä, kunnes taikina on tasaista ja irtoaa padan pohjasta. Taikinan pitää olla tahmeaa; lisää tarvittaessa vettä 1 dl kerrallaan.','Pour in the water in a stream with the machine running until the dough is smooth and leaves the bowl. It should be sticky; add water 1 dl at a time if needed.'],['Vaivaa 15 min.','Knead 15 min.'],['Jos teet yli 2 l taikinaa, jaa se 2 öljyttyyn kulhoon tai tee 2 erää. Kohota kulhossa 45 min peitettynä.','If making over 2 l, split into 2 oiled bowls or make 2 batches. Prove in the bowl 45 min covered.'],['Painele ilmat pois. Punnitse 90 g paloja, pyöritä palloiksi pakkeihin ja peitä.','Knock back. Weigh 90 g pieces, roll into balls in trays and cover.'],['Kaulitse jokainen pallo soikioksi ja öljyä pinta. Laita leivinpaperin pala väliin ja taita soikion toinen puoli paperin päälle. 10 kpl per pelti. HUOM! Älä käytä jauhoja kaulitsemiseen!','Roll each ball into an oval and oil the top. Put a piece of baking paper in the middle and fold the other half over. 10 per tray. NOTE: do not use flour for rolling!'],['Kohota pinnassa peitettynä n. 30 min.','Prove on the bench covered for about 30 min.'],['Höyrytä uunissa kypsiksi n. 8 min.','Steam in the oven until cooked, about 8 min.']]}]},
{id:'valkosuklaa-cappuccinokakku',c:'kakku',n:['Valkosuklaa-cappuccinokakku','White chocolate cappuccino cake'],f:'2297',note:['1× = 1 kakku. 4 ja 6 kakkua = 4× ja 6×. Espresso on vaihdettu käsin: 1 kakkuun 2,5 tl espressojauhetta + 1,5 dl täysmaitoa.','1× = 1 cake. 4 and 6 cakes = 4× and 6×. Espresso changed by hand: per cake 2.5 tsp espresso powder + 1.5 dl whole milk.'],p:[{t:['Pohja','Base'],i:[[200,'g','Keksi (digestive)','Digestive biscuits'],[50,'g','Voi','Butter']],s:[['Jauha keksit ja voi kutterissa. Jaa vuokiin ja painele vuoan pohjalle.','Blitz the biscuits and butter in the cutter. Divide into tins and press into the bottom.']]},{t:['Valkosuklaatäyte','White chocolate filling'],i:[[200,'g','Tuorejuusto','Cream cheese'],[300,'g','Kerma','Cream'],[50,'g','Sokeri','Sugar'],[200,'g','Valkosuklaa','White chocolate'],[1,'rkl','Vesi','Water'],[2,'kpl','Liivatelehti','Gelatine sheet']],s:[['Sulata suklaa. Laita liivatteet likoamaan kylmään veteen.','Melt the chocolate. Soak the gelatine in cold water.'],['Vatkaa kerma löysäksi vaahdoksi. Lisää vatkaten tuorejuusto ja sokeri.','Whip the cream to soft peaks. Whisk in the cream cheese and sugar.'],['Lisää sulanut suklaa vaahtoon.','Add the melted chocolate.'],['Kuumenna vesi ja sulata liivatteet siihen. Lisää ohuena nauhana vaahtoon.','Heat the water and melt the gelatine in it. Add in a thin stream.'],['Jaa vuokiin keksipohjan päälle ja laita kylmään toisen massan teon ajaksi.','Spread over the biscuit base and chill while you make the second layer.']]},{t:['Cappuccinotäyte','Cappuccino filling'],i:[[200,'g','Tuorejuusto','Cream cheese'],[300,'g','Kerma','Cream'],[100,'g','Sokeri','Sugar'],[2.5,'tl','Espressojauhe','Espresso powder'],[1.5,'dl','Täysmaito','Whole milk'],[4,'kpl','Liivatelehti','Gelatine sheet']],s:[['Liota liivatteet. Sekoita espressojauhe lämpimään maitoon.','Soak the gelatine. Stir the espresso powder into warm milk.'],['Sulata liivatteet pieneen määrään espressomaitoa ja kaada takaisin muuhun espressomaitoon.','Melt the gelatine in a little of the espresso milk and pour it back into the rest.'],['Vatkaa kerma löysäksi vaahdoksi ja lisää tuorejuusto ja sokeri.','Whip the cream to soft peaks and add the cream cheese and sugar.'],['Kaada espressomaito tuorejuusto-sokeriseokseen koko ajan sekoittaen.','Pour the espresso milk into the cream cheese mix while stirring.'],['Levitä valkosuklaakerroksen päälle ja anna hyytyä kylmässä.','Spread on the white chocolate layer and let set in the cold.']],gen:1}]},
{id:'kaura-kookoscookies',c:'leivos',n:['Kaura-kookoscookies','Oat and coconut cookies'],f:'2298',note:['Taikinapötkö 800 g, keksi 80 g. Teipissä käsin pienemmät erät (n. 6 pötköä: voi 1600 g jne.).','Dough log 800 g, cookie 80 g. The tape has smaller batches by hand (about 6 logs: butter 1600 g etc.).'],p:[{i:[[4800,'g','Voi','Butter'],[3000,'g','Sokeri','Sugar'],[3600,'g','Vehnäjauho','Wheat flour'],[1600,'g','Kaurahiutale','Oat flakes'],[1600,'g','Kookoshiutale','Desiccated coconut'],[80,'g','Ruokasooda','Baking soda']],s:[['Vatkaa voita ja sokeria lapavatkaimella, kunnes voi hieman pehmenee.','Beat the butter and sugar with the paddle until the butter softens a little.'],['Sekoita kuivat aineet keskenään ja lisää voi-sokerimassaan.','Mix the dry ingredients and add to the butter-sugar mass.'],['Punnitse 800 g paloja, pyörittele pötköiksi ja kääri leivinpaperiin. Laita pakkaseen.','Weigh 800 g pieces, roll into logs, wrap in baking paper and freeze.'],['Leikkaa pötköstä 80 g paloja ja painele keksit paperoiduille pelleille.','Cut 80 g pieces and press onto lined trays.'],['Paista 180 °C 25 min.','Bake at 180 °C for 25 min.']]}]},
{id:'vaniljasas',c:'kastike',n:['Vaniljasås','Vanilla custard sauce'],f:'2299',p:[{i:[[250,'g','Maito','Milk'],[60,'g','Keltuainen','Egg yolk'],[60,'g','Sokeri','Sugar'],[20,'g','Maizena','Cornflour'],[12,'g','Voi','Butter'],[0.5,'kpl','Vaniljatanko','Vanilla pod']],s:[['Mittaa aineet kattilaan. Halkaise vaniljatanko ja kaavi siemenet joukkoon. Laita myös tangon kuori mukaan.','Measure everything into a pot. Split the vanilla pod and scrape in the seeds. Add the pod too.'],['Keitä, kunnes sakenee.','Cook until it thickens.'],['Nosta vaniljatanko pois, kun kastike on jäähtynyt.','Remove the pod once the sauce has cooled.']]}]},
{id:'vaahtokarkkibrownie',c:'kakku',n:['Vaahtokarkkibrownie','Marshmallow brownie'],f:'2300',note:['1× = 1 GN. 3 GN = 3×.','1× = 1 GN. 3 GN = 3×.'],p:[{i:[[429,'g','Vehnäjauho','Wheat flour'],[2.5,'g','Leivinjauhe','Baking powder'],[3,'g','Suola','Salt'],[180,'g','Voi','Butter'],[156,'g','Kaakaojauhe','Cocoa powder'],[750,'g','Sokeri','Sugar'],[15,'ml','Vanilja-aromi','Vanilla extract'],[3,'kpl','Kananmuna','Egg'],[6,'kpl','Valkuainen','Egg white'],[250,'g','Vaahtokarkit (1 pss)','Marshmallows (1 bag)'],[4,'dl','Rouhittu pekaanipähkinä','Chopped pecans'],[2,'dl','Tumma suklaanapit','Dark chocolate buttons']],s:[['Sekoita jauhot, leivinjauhe ja suola.','Mix the flour, baking powder and salt.'],['Sulata voi kattilassa, kunnes se sihisee. Lisää kaakao ja sokeri ja sekoita. Anna hetki jäähtyä.','Melt the butter in a pot until it sizzles. Add the cocoa and sugar and stir. Let cool a moment.'],['Lisää vanilja-aromi ja munat. Sekoita hyvin. Lisää jauhot.','Add the vanilla and eggs. Mix well. Add the flour.'],['Jaa massa leivinpaperoituihin pakkeihin, tasoita pinta, kelmuta ja nosta yöksi kylmään.','Spread into lined trays, smooth, cover with film and chill overnight.'],['Nosta huoneenlämpöön n. 30 min ennen paistoa. Painele vaahtokarkit pintaan ja ripottele pähkinät ja suklaat päälle.','Bring to room temperature about 30 min before baking. Press in the marshmallows and sprinkle the nuts and chocolate on top.'],['Paista 175 °C ensin 10 min, peitä sitten pakki pellillä tai foliolla ja paista vielä 10 min.','Bake at 175 °C for 10 min, then cover with a tray or foil and bake 10 more min.']]}]},
{id:'marianne-juustokakku',c:'kakku',n:['Marianne-juustokakku','Marianne cheesecake'],f:'2301',note:['1× = 1 kakku. 3 ja 4 kakkua = 3× ja 4×. Maitorahkan voi vaihtaa kreikkalaiseen jogurttiin.','1× = 1 cake. 3 and 4 cakes = 3× and 4×. The quark can be swapped for Greek yogurt.'],p:[{t:['Pohja','Base'],i:[[230,'g','Dominokeksit','Domino biscuits'],[75,'g','Voi','Butter']],s:[['Murskaa keksit kutterissa ja lisää sulatettu voi. Painele vuoan pohjalle ja siirrä kylmään.','Blitz the biscuits and add the melted butter. Press into the tin and chill.']]},{t:['Täyte','Filling'],i:[[4.5,'kpl','Liivatelehti','Gelatine sheet'],[2,'rkl','Maito','Milk'],[4,'dl','Kerma','Cream'],[200,'g','Tuorejuusto','Cream cheese'],[250,'g','Maitorahka (tai kreikkalainen jogurtti)','Quark (or Greek yogurt)'],[1,'pss','Marianne crush -rouhe','Marianne crush pieces'],[0.5,'dl','Sokeri','Sugar']],s:[['Vaahdota kerma ja laita kylmään odottamaan.','Whip the cream and chill.'],['Laita liivatteet likoamaan kylmään veteen.','Soak the gelatine in cold water.'],['Sekoita keskenään tuorejuusto, rahka, karamellirouhe ja sokeri.','Mix the cream cheese, quark, candy pieces and sugar.'],['Kuumenna maito ja lisää liivatteet. Kaada ohuena nauhana tuorejuustoseokseen koko ajan sekoittaen.','Heat the milk and add the gelatine. Pour in a thin stream into the cream cheese mix while stirring.'],['Kääntele joukkoon kermavaahto.','Fold in the whipped cream.'],['Jaa tasaisesti vuokiin keksipohjan päälle.','Spread evenly over the biscuit bases.']]}]},
{id:'tiramisu-gluteeniton',c:'jalki',n:['Tiramisu (gluteeniton)','Tiramisu (gluten-free)'],f:'2302',note:['Paperissa käsin 3× määrät keksien ja mascarponevaahdon osalle. Ota ämpäristä vain puhtailla ottimilla. Älä kostuta keksejä ämpärissä, vaan ota lientä erilliseen kulhoon.','Paper has 3× amounts by hand for the biscuits and mascarpone foam. Only use clean ladles in the bucket. Do not dip biscuits in the bucket; take the liquid into a separate bowl.'],p:[{t:['Tiramisukeksit','Tiramisu biscuits'],i:[[3,'kpl','Kananmuna','Egg'],[135,'g','Sokeri','Sugar'],[1,'g','Suola','Salt'],[125,'g','Gluteenittomat jauhot','Gluten-free flour'],[15,'g','Maizena','Cornflour'],[null,'','Tomusokeri pinnalle','Icing sugar for the top']],s:[['Yhdistä munat, sokeri ja suola ja lämmitä vesihauteessa 70 °C:een.','Combine the eggs, sugar and salt and heat over a water bath to 70 °C.'],['Vaahdota kovaksi vaahdoksi.','Whisk to a stiff foam.'],['Siivilöi jauhot ja maizena joukkoon.','Sift in the flour and cornflour.'],['Pursota pelleille ja tomusokeroi pinta.','Pipe onto trays and dust with icing sugar.'],['Paista 175 °C 11 min.','Bake at 175 °C for 11 min.']]},{t:['Mascarponevaahto','Mascarpone foam'],i:[[120,'g','Keltuainen','Egg yolk'],[102,'g','Sokeri','Sugar'],[0.6,'dl','Kerma','Cream'],[1,'tl','Vanilja-aromi','Vanilla extract'],[675,'g','Mascarpone','Mascarpone'],[1.8,'dl','Kuohukerma','Whipping cream']],s:[['Vatkaa keltuaiset ja sokeri hetki, lisää 0,6 dl kermaa.','Whisk the yolks and sugar a moment, add 0.6 dl cream.'],['Lämmitä vesihauteessa koko ajan kevyesti vatkaten 75 °C:een.','Heat over a water bath to 75 °C, whisking gently all the time.'],['Anna jäähtyä. Vaahdota vanilja-aromi ja mascarpone kovaksi vaahdoksi.','Let cool. Whip the vanilla and mascarpone until firm.'],['Lisää keltuaiset ja vaahdota vielä lisää.','Add the yolk mix and whisk more.'],['Vaahdota 1,8 dl kuohukermaa erikseen ja sekoita mascarponemassaan. Pussita.','Whip 1.8 dl cream separately and fold into the mascarpone. Put into piping bags.'],['Jos vaahto löystyy kylmässä seistessä, voit vaahdottaa sen uudelleen.','If the foam loosens in the fridge, you can whip it again.']]},{t:['Kostutusliemi','Soaking liquid'],i:[[2.5,'l','Espresso','Espresso'],[2.5,'dl','Amaretto','Amaretto'],[2.5,'dl','Marsala','Marsala']],s:[['Sekoita espresso, amaretto ja marsala.','Mix the espresso, amaretto and marsala.']],gen:1}]},
{id:'vadelmatayte',c:'kreemi',n:['Vadelmatäyte ja namalaka','Raspberry filling and namelaka'],f:'2303',note:['Vadelmatäyte 1 kakulle.','Raspberry filling for 1 cake.'],p:[{t:['Vadelmatäyte (1 kakku)','Raspberry filling (1 cake)'],i:[[400,'g','Maitorahka','Quark'],[250,'g','Mascarpone','Mascarpone'],[4,'rkl','Tomusokeri','Icing sugar'],[2,'tl','Vaniljasokeri','Vanilla sugar'],[1,'dl','Vadelmakastike','Raspberry sauce']],s:[['Sekoita kaikki raaka-aineet keskenään.','Mix everything together.']]},{t:['Vadelmakastike','Raspberry sauce'],i:[[600,'g','Vadelmat','Raspberries'],[1.5,'dl','Hyytelösokeri','Jam sugar']],s:[['Kiehauta vadelmat ja paseeraa siivilän läpi.','Boil the raspberries and pass through a sieve.'],['Laita pyree kattilaan ja kuumenna kiehuvaksi.','Put the purée back in the pot and bring to the boil.'],['Lisää hyytelösokeri, ota pois liedeltä ja anna jäähtyä hyvin.','Add the jam sugar, take off the heat and cool well.']]},{t:['Namalaka (paahdettu valkosuklaa)','Namelaka (toasted white chocolate)'],i:[[1000,'g','Valkosuklaa','White chocolate'],[30,'g','Glukoosisiirappi','Glucose syrup'],[600,'g','Maito','Milk'],[1200,'g','Kerma','Cream'],[6,'kpl','Liivatelehti','Gelatine sheet']],s:[['Paahda suklaata 130 °C n. 45 min.','Toast the chocolate at 130 °C for about 45 min.'],['Kiehauta maito ja kerma kattilassa.','Boil the milk and cream.'],['Lisää glukoosisiirappi sekä liotetut liivatteet.','Add the glucose and the soaked gelatine.'],['Kaada kermaseos paahdetun suklaan joukkoon ja poraa tasaiseksi.','Pour over the toasted chocolate and blend smooth.'],['Anna jähmettyä kylmässä seuraavaan päivään.','Let set in the cold until the next day.']]}]},
{id:'lakritsi-passiontayte',c:'kreemi',n:['Lakritsi-salmiakkitäyte ja passiontäyte','Licorice-salmiakki filling and passion filling'],f:'2304',note:['Molemmat 1 kakulle.','Both for 1 cake.'],p:[{t:['Lakritsi-salmiakkitäyte','Licorice-salmiakki filling'],i:[[3,'dl','Kerma','Cream'],[200,'g','Tuorejuusto','Cream cheese'],[null,'','Lakritsi-salmiakkikastike','Licorice-salmiakki sauce'],[null,'','Turkinpippurirouhe','Crushed Tyrkisk Peber']],s:[['Vatkaa kerma vaahdoksi.','Whip the cream.'],['Notkista tuorejuusto ja lisää kermavaahtoon.','Loosen the cream cheese and add to the cream.'],['Mausta lakritsi-salmiakkikastikkeella ja Turkinpippurirouheella.','Flavour with licorice-salmiakki sauce and crushed Tyrkisk Peber.']]},{t:['Passiontäyte','Passion filling'],i:[[2.5,'dl','Kerma','Cream'],[200,'g','Mascarpone','Mascarpone'],[4,'rkl','Tomusokeri','Icing sugar'],[1,'dl','Passionpyree','Passion fruit purée'],[null,'','Vaniljakreemijauhe (tarvittaessa)','Vanilla custard powder (if needed)']],s:[['Vatkaa kerma vaahdoksi.','Whip the cream.'],['Notkista mascarpone ja tomusokeri ja lisää kermavaahtoon.','Loosen the mascarpone with the icing sugar and add to the cream.'],['Lisää passionpyree.','Add the passion purée.'],['Sekoita joukkoon vaniljakreemijauhetta, jos massa tuntuu liian löysältä.','Add vanilla custard powder if it feels too loose.']]}]},
{id:'pomada',c:'koriste',n:['Pomada (fondant)','Pomada (fondant)'],v:1,f:'2305',p:[{i:[[675,'g','Sokeri','Sugar'],[150,'g','Vesi','Water'],[140,'g','Glukoosisiirappi','Glucose syrup']],s:[['Mittaa ainekset kattilaan ja keitä sekoittamatta 115 °C:een.','Put everything in a pot and boil without stirring to 115 °C.'],['Kaada massa yleiskoneen kulhoon ja anna jäähtyä 60 °C:een.','Pour into the mixer bowl and let cool to 60 °C.'],['Vatkaa valkoiseksi ja kuohkeaksi lapavatkaimella.','Beat with the paddle until white and fluffy.'],['Kaada kelmutettuun astiaan, kääri kelmu kiinni ja anna tekeytyä seuraavaan päivään.','Pour into a film-lined container, wrap it closed and let rest until the next day.'],['Lämmitä tarvittava määrä lyhyissä pätkissä mikrossa. Lisää tarvittaessa hieman vettä. VARO! Pomada kuumenee todella kuumaksi!','Warm what you need in short bursts in the microwave. Add a little water if needed. CAREFUL: it gets very hot!']]}]},
{id:'langa',c:'taikina',n:['Långa (saaristolaisleipä)','Långa (archipelago loaf)'],f:'2306',note:['1× = 6 leipää. Paperissa myös 4 kpl ja käsin 3 ja 2 kpl. Pala 1100–1250 g. Höyryä käytetty 3 kertaa.','1× = 6 loaves. Paper also has 4 and by hand 3 and 2 loaves. Piece 1100–1250 g. Steam has been used 3 times.'],p:[{i:[[450,'g','Muscovadosokeri','Muscovado sugar'],[1125,'g','Raski','Raski (rye mash)'],[1800,'g','Kuuma vesi','Hot water'],[105,'g','Hunaja','Honey'],[3300,'g','Luomu vehnäjauho','Organic wheat flour'],[60,'g','Tuorehiiva','Fresh yeast'],[120,'g','Atlantin merisuola','Atlantic sea salt']],s:[['Sekoita ensin sokeri, hunaja, raski ja kuuma vesi.','First mix the sugar, honey, raski and hot water.'],['Punnitse pataan vehnäjauhot ja hiiva.','Weigh the flour and yeast into the bowl.'],['Lisää vesi-raskiseos.','Add the water-raski mix.'],['Aja nopeudella 1 n. 10 min, lisää suola ja tarkasta jauhomäärä. Aja nopeudella 1 vielä 5 min.','Run on speed 1 for about 10 min, add the salt and check the flour. Run 5 more min on speed 1.'],['Anna taikinan levätä vähintään puoli tuntia.','Rest the dough at least half an hour.'],['Jaa 1100–1250 g paloihin ja taittele öljyttyihin rasioihin kylmään yön yli.','Divide into 1100–1250 g pieces and fold into oiled boxes; chill overnight.'],['Esilämmitä uuni 250 °C, laita leivät uuniin, höyrytä hyvin, sammuta uuni ja anna olla 20 min.','Preheat to 250 °C, put the loaves in, steam well, turn off the oven and leave 20 min.'],['Laita uuni päälle 175 °C ja paista n. 30 min.','Turn the oven on at 175 °C and bake about 30 min.']]}]},
];
var W = [];
